  Config.define("esp.friendColor", util.hex("45DDA8"))
  Config.define("esp.seenTint", false)
  Config.define("esp.seenColor", util.hex("FFD166"))
  Config.define("esp.markTarget", true)
  Config.define("esp.targetColor", util.hex("FF6B6B"))
  Config.define("esp.range", 3000)
  Config.define("esp.nameRange", FAR)
  Config.define("esp.skeletonRange", 500)
  Config.define("esp.maxPlayers", EVERYONE)
  Config.define("esp.teamCheck", false)
  Config.define("esp.displayNames", true)
  Config.define("esp.textSize", 13)
  Config.define("esp.thickness", 2)
  Config.define("esp.tracerFrom", "bottom")
  Config.define("esp.arrowSize", 18)
  Config.define("esp.arrowRadius", 36)
  Config.define("esp.arrowDistance", true)
  Config.define("esp.fade", true)
  Config.define("esp.fadeFrom", 55)
  Config.define("esp.dimHidden", false)
  Config.define("esp.hideHidden", false)
  Config.define("esp.chamsFill", 75)
  Config.define("esp.chamsOutline", true)
end

function Esp.start()
  if Esp.started then return end
  Esp.started = true
  Esp.define()
  Roster.start()
  gui = B.screen(8000)
  layer = UI.frame(gui, { Name = "Esp", Size = UDim2.fromScale(1, 1) })
  arrowLayer = UI.frame(gui, { Name = "Arrows", Size = UDim2.fromScale(1, 1) })
  highlights = Instance.new("Folder")
  highlights.Name = util.randomName()
  highlights.Parent = gui
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "esp.enabled", box = "esp.box", fill = "esp.fill", boxWidth = "esp.boxWidth", minSize = "esp.minSize", colorMode = "esp.colorMode",
    color = "esp.color", friendColor = "esp.friendColor", seenTint = "esp.seenTint", seenColor = "esp.seenColor", markTarget = "esp.markTarget",
    targetColor = "esp.targetColor", range = "esp.range", nameRange = "esp.nameRange", skeletonRange = "esp.skeletonRange", maxPlayers = "esp.maxPlayers",
    teamCheck = "esp.teamCheck", displayNames = "esp.displayNames", textSize = "esp.textSize", thickness = "esp.thickness", tracerFrom = "esp.tracerFrom",
    arrowSize = "esp.arrowSize", arrowRadius = "esp.arrowRadius", arrowDistance = "esp.arrowDistance", fade = "esp.fade", fadeFrom = "esp.fadeFrom",
    dimHidden = "esp.dimHidden", hideHidden = "esp.hideHidden", chamsFill = "esp.chamsFill", chamsOutline = "esp.chamsOutline" })
  Esp.options = O
  local function elements(list)
    table.clear(want)
    for _, name in ipairs(list) do want[name] = true end
  end
  elements(Config.get("esp.elements"))
  Config.on("esp.elements", elements)
  Esp.want = want
  Config.on("esp.enabled", setRunning, true)
  -- a player who left takes their overlay with them
  Roster.changed:connect(function(entry)
    if entry.gone then
      local object = Esp.objects[entry]
      if object then object:destroy(); Esp.objects[entry] = nil end
    end
  end)
  B.own(function() setRunning(false) end)
end
end
do -- 23_aim.lua
-- ============================================================================
--  23 aim      aim assist, FOV ring, triggerbot
--
--  Two ways to turn toward a target. "Mouse" feeds relative mouse movement to
--  the game, so the game's own camera does the turning (works with any camera
--  script, first or third person). "Camera" writes the camera's CFrame, for
--  games that leave the default camera alone. Both close the gap by a fraction
--  per frame derived from frame time, so the feel is the same at 60 and 240 fps,
--  and each axis can have its own.
--
--  Far targets need three things the first version did not have: a range with
--  no ceiling, a line of sight that is cast in lengths a ray can see along (one
--  ray finds nothing past 15,000 studs, which read as "in view"), and a lead
--  that knows a shot takes time to arrive and falls on the way.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Roster, Hud, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Roster, B.Hud, B.Assets
local UIS = S.UserInputService
local Aim = { target = nil, active = false }
B.Aim = Aim
local FAR = 100000        -- the last stop of the Range slider: no limit
local WHOLE = 2500        -- the last stop of the circle: the whole screen
Aim.FAR, Aim.WHOLE = FAR, WHOLE
local O
local wantParts = {}
local rayParams
local ring, ringStroke, mark, markStroke, crossA, crossB, snap, note, gui
local toggled = false
local lostAt = -math.huge     -- when the last target was lost: a new one waits out the switch delay
local onSince, onWho = nil, nil
local canMouse = type(mousemoverel) == "function"
Aim.canMouse = canMouse
Aim.canClick = type(mouse1click) == "function" or (type(mouse1press) == "function" and type(mouse1release) == "function")

local function aimPoint(entry, camera, origin)
  -- returns the part to aim at, where it is on screen, and how far that is from the crosshair
  local best, bestScreen, bestDistance
  local function consider(part)
    if not part then return end
    local p = camera:WorldToViewportPoint(part.Position + Vector3.new(0, O.offset, 0))
    if p.Z <= 0 then return end
    local d = (Vector2.new(p.X, p.Y) - origin).Magnitude
    if not bestDistance or d < bestDistance then best, bestScreen, bestDistance = part, p, d end
  end
  local joints = entry.joints
  if wantParts.nearest then
    consider(entry.head); consider(joints.UpperTorso or joints.Torso); consider(entry.root); consider(joints.LowerTorso)
  else
    local part = (wantParts.head and entry.head) or (wantParts.torso and (joints.UpperTorso or joints.Torso)) or (wantParts.root and entry.root) or entry.head or entry.root
    consider(part)
  end
  return best, bestScreen, bestDistance
end

-- Is there a clear line from the camera to that point? With "see through glass" on, something
-- that can be seen through or walked through does not count as a wall.
local function visible(camera, entry, point)
  local from = camera.CFrame.Position
  local ignore = { B.LP.Character, entry.character }
  for _ = 1, O.wallClear and 6 or 1 do
    rayParams.FilterDescendantsInstances = ignore
    local hit = util.ray(from, point, rayParams)
    if not hit then return true end
    local part = hit.Instance
    if not (O.wallClear and part:IsA("BasePart") and (part.Transparency >= 0.8 or not part.CanCollide)) then return false end
    ignore[#ignore + 1] = part
  end
  return false
end

local function valid(entry, camPos)
  if not entry.alive or not entry.root or not entry.root.Parent then return false end
  if Roster.isHidden(entry) then return false end
  if O.teamCheck and not Roster.isEnemy(entry) then return false end
  if O.ignoreFriends and Roster.isFriend(entry) then return false end
  if O.skipShielded and entry.shielded then return false end
  if O.onlyMarked and Roster.anyTargets() and not Roster.isTarget(entry) then return false end
  return O.range >= FAR or (entry.root.Position - camPos).Magnitude <= O.range
end

-- what a candidate is ranked by: lower is better
local function rank(entry, pixels, camPos)
  if O.priority == "distance" then return (entry.root.Position - camPos).Magnitude end
  if O.priority == "health" then return (entry.health or 100) / (entry.maxHealth or 100) end
  return pixels
end
local function better(a, b)
  -- a marked target comes before anyone who is not
  if a[5] ~= b[5] then return a[5] end
  return a[4] < b[4]
end

local function pick(camera, origin, now)
  local camPos = camera.CFrame.Position
  local radius = O.fov >= WHOLE and math.huge or O.fov
  -- keep the current target while it stays valid and close to the crosshair
  local current = Aim.target
  if current then
    if valid(current, camPos) then
      if O.sticky then
        local part, screen, distance = aimPoint(current, camera, origin)
        if part and distance <= radius * 1.6 and (not O.wallCheck or visible(camera, current, part.Position)) then
          return current, part, screen
        end
      end
    else
      -- dead, gone or no longer allowed: the next one is not taken at once
      lostAt = now
    end
  end
  if now - lostAt < O.switchDelay / 1000 then return nil end
  local candidates = {}
  for _, entry in ipairs(Roster.list) do
    if valid(entry, camPos) then
      local part, screen, distance = aimPoint(entry, camera, origin)
      if part and distance <= radius then candidates[#candidates + 1] = { entry, part, screen, rank(entry, distance, camPos), Roster.isTarget(entry) } end
    end
  end
  table.sort(candidates, better)
  -- best first; at most three wall checks a frame
  for index = 1, math.min(#candidates, 3) do
    local c = candidates[index]
    if not O.wallCheck or visible(camera, c[1], c[2].Position) then return c[1], c[2], c[3] end
  end
  return nil
end

local function isActive()
  if not O.enabled then return false end
  if O.mode == "always" then return true end
  if O.mode == "toggle" then return toggled end
  return Config.keyDown(O.key)
end

local lastClick = 0
local function click()
  if type(mouse1click) == "function" then mouse1click()
  elseif type(mouse1press) == "function" then mouse1press(); task.delay(0.02, mouse1release) end
end

-- the ring, the mark on the target and the line to it all take one colour: the accent, or your own
local function paint()
  if not ring then return end
  local color = O.ownColor and O.color or T.accent
  local alpha = 1 - O.fovOpacity / 100
  ringStroke.Color, ringStroke.Thickness, ringStroke.Transparency = color, O.fovThickness, alpha
  ring.BackgroundColor3 = color
  ring.BackgroundTransparency = O.fovFill and 1 - 0.07 * O.fovOpacity / 100 or 1
  markStroke.Color, crossA.BackgroundColor3, crossB.BackgroundColor3, snap.ImageColor3 = color, color, color, color
  local style = O.markStyle
  local size = style == "ring" and 24 or 9
  mark.Size = UDim2.fromOffset(size, size)
  markStroke.Enabled = style ~= "cross"
  crossA.Visible, crossB.Visible = style == "cross", style == "cross"
end
local function hideMarks()
  if mark and mark.Visible then mark.Visible = false end
  if snap and snap.Visible then snap.Visible = false end
  if note and note.Visible then note.Visible = false end
end

local function step(dt)
  local camera = workspace.CurrentCamera
  if not camera then return end
  local now = os.clock()
  local mouse = UIS:GetMouseLocation()
  local locked = UIS.MouseBehavior == Enum.MouseBehavior.LockCenter
  local origin = locked and camera.ViewportSize * 0.5 or mouse
  if ring then
    local showRing = O.enabled and O.showFov and O.fov < WHOLE and not (B.Window.open and UI.popoverOpen())
    if ring.Visible ~= showRing then ring.Visible = showRing end
    if showRing then
      ring.Position = UDim2.fromOffset(origin.X, origin.Y)
      local d = O.fov * 2
      if ring.Size.X.Offset ~= d then ring.Size = UDim2.fromOffset(d, d) end
    end
  end
  local active = isActive() and not (B.Window.open and UIS:GetFocusedTextBox() ~= nil)
  Aim.active = active
  if active then
    local entry, part, screen = pick(camera, origin, now)
    Aim.target = entry
    if entry and part then
      local camPos = camera.CFrame.Position
      local goal = part.Position + Vector3.new(0, O.offset, 0)
      if O.predict then
        -- where they will be when it arrives: your ping, the extra asked for, and the shot's own
        -- flight if it has one, which also falls on the way
        local lead = O.lead / 1000 + (Hud and Hud.ping() or 0) / 1000
        if O.bulletSpeed > 0 then
          local flight = (goal - camPos).Magnitude / O.bulletSpeed
          lead += flight
          goal += Vector3.new(0, 0.5 * O.drop * flight * flight, 0)
        end
        goal += entry.root.AssemblyLinearVelocity * lead
        local p = camera:WorldToViewportPoint(goal)
        if p.Z > 0 then screen = p end
      end
      local offX, offY = screen.X - origin.X, screen.Y - origin.Y
      -- inside the dead zone it is close enough: no hunting about a point it is already on
      if offX * offX + offY * offY > O.deadzone * O.deadzone then
        -- fraction of the remaining gap to close this frame, each way
        local gainX = 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smooth / 100)))
        local gainY = O.split and 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smoothY / 100))) or gainX
        if O.method == "mouse" and canMouse then
          local dx, dy = offX * gainX * (O.sens / 100), offY * gainY * (O.sens / 100)
          if math.abs(dx) + math.abs(dy) > 0.05 then mousemoverel(dx, dy) end
        else
          -- turn and tilt separately, about the world's up: the camera never rolls
          local cf = camera.CFrame
          local look, to = cf.LookVector, (goal - cf.Position).Unit
          local yaw, pitch = math.atan2(-look.X, -look.Z), math.asin(math.clamp(look.Y, -1, 1))
          local turn = (math.atan2(-to.X, -to.Z) - yaw + math.pi) % (2 * math.pi) - math.pi
          local tilt = math.asin(math.clamp(to.Y, -1, 1)) - pitch
          camera.CFrame = CFrame.new(cf.Position) * CFrame.Angles(0, yaw + turn * gainX, 0) * CFrame.Angles(pitch + tilt * gainY, 0, 0)
        end
      end
      if mark then
        mark.Visible = O.showTarget
        mark.Position = UDim2.fromOffset(screen.X, screen.Y)
        local lineOn = O.snapline
        if snap.Visible ~= lineOn then snap.Visible = lineOn end
        if lineOn then
          local length = math.sqrt(offX * offX + offY * offY)
          snap.Position = UDim2.fromOffset((origin.X + screen.X) * 0.5, (origin.Y + screen.Y) * 0.5)
          snap.Size = UDim2.fromOffset(length, 3.6)
          snap.Rotation = math.deg(math.atan2(offY, offX))
        end
        local noteOn = O.targetInfo
        if note.Visible ~= noteOn then note.Visible = noteOn end
        if noteOn then
          note.Position = UDim2.fromOffset(screen.X, screen.Y + 16)
          local words = entry.display .. "  ·  " .. util.studs((entry.root.Position - camPos).Magnitude) .. " st"
          if entry.health then words ..= "  ·  " .. math.floor(entry.health + 0.5) .. " hp" end
          if note.Text ~= words then note.Text = words end
        end
      end
    else
      hideMarks()
    end
  else
    Aim.target = nil
    hideMarks()
  end

  -- triggerbot: fire when the crosshair rests on an enemy
  if O.trigger and Aim.canClick and not B.Window.open and (O.triggerMode ~= "key" or Config.keyDown(O.key)) then
    local ray = camera:ViewportPointToRay(origin.X, origin.Y)
    rayParams.FilterDescendantsInstances = { B.LP.Character }
    local reach = O.range >= FAR and FAR or O.range
    local hit = util.ray(ray.Origin, ray.Origin + ray.Direction * reach, rayParams)
    local model = hit and hit.Instance and hit.Instance:FindFirstAncestorOfClass("Model")
    local player = model and S.Players:GetPlayerFromCharacter(model)
    local entry = player and Roster.byPlayer[player]
    if entry and valid(entry, camera.CFrame.Position) and (not O.triggerHead or hit.Instance.Name == "Head") then
      -- on someone: how long for, and is it time for another shot
      if onWho ~= entry then onWho, onSince = entry, now end
      if now - onSince >= O.triggerReact / 1000 and now - lastClick > math.max(0.03, O.triggerDelay / 1000) then
        lastClick = now
        click()
      end
    else
      onWho, onSince = nil, nil
    end
  else
    onWho, onSince = nil, nil
  end
end

function Aim.define()
  Config.define("aim.enabled", false)
  Config.define("aim.mode", "hold")
  Config.define("aim.key", "MouseButton2")
  Config.define("aim.method", canMouse and "mouse" or "camera")
  Config.define("aim.fov", 140)
  Config.define("aim.showFov", true)
  Config.define("aim.fovThickness", 1.5)
  Config.define("aim.fovOpacity", 65)
  Config.define("aim.fovFill", false)
  Config.define("aim.ownColor", false)
  Config.define("aim.color", util.hex("C9C2FF"))
  Config.define("aim.showTarget", true)
  Config.define("aim.markStyle", "dot")
  Config.define("aim.snapline", false)
  Config.define("aim.targetInfo", false)
  Config.define("aim.smooth", 45)
  Config.define("aim.split", false)
  Config.define("aim.smoothY", 45)
  Config.define("aim.sens", 100)
  Config.define("aim.deadzone", 0)
  Config.define("aim.offset", 0)
  Config.define("aim.parts", { "head" })
  Config.define("aim.priority", "crosshair")
  Config.define("aim.onlyMarked", false)
  Config.define("aim.switchDelay", 0)
  Config.define("aim.teamCheck", true)
  Config.define("aim.wallCheck", true)
  Config.define("aim.wallClear", false)
  Config.define("aim.ignoreFriends", true)
  Config.define("aim.skipShielded", true)
  Config.define("aim.range", 2000)
  Config.define("aim.sticky", true)
  Config.define("aim.predict", false)
  Config.define("aim.lead", 0)
  Config.define("aim.bulletSpeed", 0)
  Config.define("aim.drop", 0)
  Config.define("aim.trigger", false)
  Config.define("aim.triggerMode", "always")
  Config.define("aim.triggerDelay", 80)
  Config.define("aim.triggerReact", 0)
  Config.define("aim.triggerHead", false)
end

function Aim.start()
  if Aim.started then return end
  Aim.started = true
  Aim.define()
  Roster.start()
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "aim.enabled", mode = "aim.mode", key = "aim.key", method = "aim.method", fov = "aim.fov", showFov = "aim.showFov",
    fovThickness = "aim.fovThickness", fovOpacity = "aim.fovOpacity", fovFill = "aim.fovFill", ownColor = "aim.ownColor", color = "aim.color",
    showTarget = "aim.showTarget", markStyle = "aim.markStyle", snapline = "aim.snapline", targetInfo = "aim.targetInfo", smooth = "aim.smooth",
    split = "aim.split", smoothY = "aim.smoothY", sens = "aim.sens", deadzone = "aim.deadzone", offset = "aim.offset", priority = "aim.priority",
    onlyMarked = "aim.onlyMarked", switchDelay = "aim.switchDelay", teamCheck = "aim.teamCheck", wallCheck = "aim.wallCheck", wallClear = "aim.wallClear",
    ignoreFriends = "aim.ignoreFriends", skipShielded = "aim.skipShielded", range = "aim.range", sticky = "aim.sticky", predict = "aim.predict",
    lead = "aim.lead", bulletSpeed = "aim.bulletSpeed", drop = "aim.drop", trigger = "aim.trigger", triggerMode = "aim.triggerMode",
    triggerDelay = "aim.triggerDelay", triggerReact = "aim.triggerReact", triggerHead = "aim.triggerHead" })
  Aim.options = O
  local function parts(list)
    table.clear(wantParts)
    for _, name in ipairs(list) do wantParts[name] = true end
  end
  parts(Config.get("aim.parts"))
  Config.on("aim.parts", parts)

  gui = B.screen(8500)
  ring = UI.frame(gui, { Name = "Fov", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(280, 280), Visible = false })
  UI.corner(ring, true)
  ringStroke = Instance.new("UIStroke")
  ringStroke.Parent = ring
  -- the line from the crosshair to the target, under the mark
  snap = UI.new("ImageLabel", { Name = "Snap", BackgroundTransparency = 1, Image = Assets.image("line") or "", AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 0.35,
    Visible = false, Parent = gui })
  mark = UI.frame(gui, { Name = "Target", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(9, 9), Visible = false, BackgroundTransparency = 1 })
  UI.corner(mark, true)
  markStroke = Instance.new("UIStroke")
  markStroke.Thickness = 1.5
  markStroke.Parent = mark
  crossA = UI.frame(mark, { Name = "CrossA", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = 45,
    BackgroundTransparency = 0, Visible = false })
  crossB = UI.frame(mark, { Name = "CrossB", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = -45,
    BackgroundTransparency = 0, Visible = false })
  note = UI.new("TextLabel", { Name = "Note", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Size = UDim2.fromOffset(320, 14), FontFace = B.F.mono500,
    TextSize = 11, Text = "", TextColor3 = Color3.new(1, 1, 1), TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.5, Visible = false, Parent = gui })
  paint()
  for _, id in ipairs({ "aim.fovThickness", "aim.fovOpacity", "aim.fovFill", "aim.ownColor", "aim.color", "aim.markStyle", "app.accent", "app.scheme" }) do
    Config.on(id, function() task.defer(paint) end)
  end

  B.connect(UIS.InputBegan, function(input, processed)
    if O.mode ~= "toggle" or not O.enabled or Config.capturing then return end
    if input.UserInputType == Enum.UserInputType.Keyboard and UIS:GetFocusedTextBox() then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard and processed then return end
    if Config.keyName(input) == O.key then toggled = not toggled end
  end, "aim.toggle")

  local running = false
  local function refresh()
    local need = O.enabled or O.trigger
    if need == running then return end
    running = need
    if need then
      S.RunService:BindToRenderStep("BasedAim", Enum.RenderPriority.Camera.Value + 1, function(dt)
        local ok, err = pcall(step, dt)
        if not ok then B.fault("aim", err); Config.set("aim.enabled", false); Config.set("aim.trigger", false) end
      end)
    else
      pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end)
      ring.Visible = false
      hideMarks()
      Aim.target, Aim.active = nil, false
    end
  end
  Config.on("aim.enabled", refresh)
  Config.on("aim.trigger", refresh)
  refresh()
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end) end)
end
end
do -- 24_move.lua
-- ============================================================================
--  24 move     speed, jump, noclip, click teleport, gravity
--
--  Everything here restores what it changed when it is switched off, and
--  re-applies itself after a respawn. Flight lives in 26_flight.
-- ============================================================================
local S, Config = B.S, B.Config
local UIS = S.UserInputService
local Move = {}
B.Move = Move
local O
local saved = {}          -- original humanoid values, per character

local function parts()
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
  return character, humanoid, root
end
local function remember(humanoid)
  if saved.humanoid ~= humanoid then
    saved = { humanoid = humanoid, WalkSpeed = humanoid.WalkSpeed, JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight, UseJumpPower = humanoid.UseJumpPower }
  end
end

-- ---------------------------------------------------------------- noclip
local noclip = { character = nil, list = {}, changed = {}, added = nil }
local function noclipStep()
  local character = B.character()
  if not character then return end
  if noclip.character ~= character then
    if noclip.added then noclip.added:Disconnect() end
    noclip.character, noclip.list, noclip.changed = character, {}, {}
    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end
    noclip.added = character.DescendantAdded:Connect(function(part)
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end)
  end
  for _, part in ipairs(noclip.list) do
    if part.CanCollide then
      part.CanCollide = false
      noclip.changed[part] = true
    end
  end
end
local function stopNoclip()
  if noclip.added then noclip.added:Disconnect() end
  for part in pairs(noclip.changed) do
    -- only the parts that normally collide get it back
    local name = part.Name
    if part.Parent and (name == "HumanoidRootPart" or name == "Torso" or name == "UpperTorso" or name == "LowerTorso" or name == "Head") then part.CanCollide = true end
  end
  noclip = { character = nil, list = {}, changed = {}, added = nil }
end

-- ---------------------------------------------------------------- per-step work
local function physics(dt)
  local _, humanoid, root = parts()
  if not humanoid or not root then return end
  if O.speed or O.jump then remember(humanoid) end
  if O.speed then
    if O.speedMode == "cframe" then
      local direction = humanoid.MoveDirection
      local flight = B.Flight and B.Flight.state
      if direction.Magnitude > 0.05 and flight ~= "flying" and flight ~= "landing" then
        root.CFrame += direction * math.max(0, O.speedValue - humanoid.WalkSpeed) * dt
      end
    elseif humanoid.WalkSpeed ~= O.speedValue then
      humanoid.WalkSpeed = O.speedValue
    end
  end
  if O.jump then
    if not humanoid.UseJumpPower then humanoid.UseJumpPower = true end
    if humanoid.JumpPower ~= O.jumpValue then humanoid.JumpPower = O.jumpValue end
  end
end
local function restore(what)
  local humanoid = saved.humanoid
  if not humanoid or not humanoid.Parent then return end
  if what == "speed" then humanoid.WalkSpeed = saved.WalkSpeed end
  if what == "jump" then
    humanoid.UseJumpPower = saved.UseJumpPower
    humanoid.JumpPower, humanoid.JumpHeight = saved.JumpPower, saved.JumpHeight
  end
end

function Move.teleport(position)
  local _, _, root = parts()
  if not root then return false end
  root.CFrame = CFrame.new(position) * root.CFrame.Rotation
  root.AssemblyLinearVelocity = Vector3.zero
  return true
end

function Move.define()
  Config.define("move.speed", false)
  Config.define("move.speedValue", 32)
  Config.define("move.speedMode", "humanoid")
  Config.define("move.jump", false)
  Config.define("move.jumpValue", 80)
  Config.define("move.infJump", false)
  Config.define("move.noclip", false)
  Config.define("move.clickTp", false)
  Config.define("move.gravity", false)
  Config.define("move.gravityValue", 80)
end

function Move.start()
  if Move.started then return end
  Move.started = true
  Move.define()
  O = Config.mirror({ speed = "move.speed", speedValue = "move.speedValue", speedMode = "move.speedMode",
    jump = "move.jump", jumpValue = "move.jumpValue", infJump = "move.infJump", noclip = "move.noclip", clickTp = "move.clickTp",
    gravity = "move.gravity", gravityValue = "move.gravityValue" })
  Move.options = O
  B.connect(S.RunService.Heartbeat, physics, "move.physics")
  B.connect(S.RunService.Stepped, function() if O.noclip then noclipStep() end end, "move.noclip")
  Config.on("move.noclip", function(on) if not on then stopNoclip() end end)
  Config.on("move.speed", function(on) if not on then restore("speed") end end)
  Config.on("move.speedMode", function() restore("speed") end)
  Config.on("move.jump", function(on) if not on then restore("jump") end end)
  local baseGravity = workspace.Gravity
  local function gravity()
    workspace.Gravity = O.gravity and O.gravityValue or baseGravity
  end
  Config.on("move.gravity", gravity)
  Config.on("move.gravityValue", gravity)
  if O.gravity then gravity() end
  B.connect(UIS.JumpRequest, function()
    if not O.infJump then return end
    local _, humanoid = parts()
    if humanoid and humanoid.Health > 0 then humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end
  end, "move.infjump")
  B.connect(UIS.InputBegan, function(input, processed)
    if not O.clickTp or processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not UIS:IsKeyDown(Enum.KeyCode.LeftControl) then return end
    local camera = workspace.CurrentCamera
    local mouse = UIS:GetMouseLocation()
    local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { B.LP.Character }
    -- as far as there is anything to click on: cast in lengths a ray can see along
    local hit = B.util.ray(ray.Origin, ray.Origin + ray.Direction * 100000, params)
    if hit then Move.teleport(hit.Position + Vector3.new(0, 3.2, 0)) end
  end, "move.clicktp")
  B.own(function()
    stopNoclip(); restore("speed"); restore("jump")
    workspace.Gravity = baseGravity
  end)
end
end
do -- 25_world.lua
-- ============================================================================
--  25 world    lighting, camera, crosshair, server tools
-- ============================================================================
local S, util, Motion, Theme, UI, Config, Window = B.S, B.util, B.Motion, B.Theme, B.UI, B.Config, B.Window
local Lighting = S.Lighting
local World = {}
B.World = World
local Server = {}
B.Server = Server
local O

-- ---------------------------------------------------------------- lighting
local LIGHT = { "Brightness", "ClockTime", "FogEnd", "FogStart", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }
local original = nil
local atmospheres = {}
local function capture()
  if original then return end
  original = {}
  for _, key in ipairs(LIGHT) do original[key] = Lighting[key] end
end
local function applyLighting()
  local bright, noFog, time = O.fullbright, O.noFog, O.time
  if not (bright or noFog or time) then return end
  capture()
  if bright then
    if Lighting.Brightness ~= O.brightValue then Lighting.Brightness = O.brightValue end
    if Lighting.GlobalShadows then Lighting.GlobalShadows = false end
    local white = Color3.fromRGB(178, 178, 178)
    if Lighting.Ambient ~= white then Lighting.Ambient = white end
    if Lighting.OutdoorAmbient ~= white then Lighting.OutdoorAmbient = white end
    if Lighting.ExposureCompensation ~= 0 then Lighting.ExposureCompensation = 0 end
  end
  if time or bright then
    local clock = time and O.timeValue or 14
    if math.abs(Lighting.ClockTime - clock) > 0.02 then Lighting.ClockTime = clock end
  end
  if noFog or bright then
    if Lighting.FogEnd < 9e5 then Lighting.FogEnd = 1e6 end
    for _, child in ipairs(Lighting:GetChildren()) do
      if child:IsA("Atmosphere") then
        if atmospheres[child] == nil then atmospheres[child] = child.Density end
        if child.Density ~= 0 then child.Density = 0 end
      end
    end
  end
end
local function restoreLighting()
  if not original then return end
  if not O.fullbright then
    for _, key in ipairs({ "Brightness", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }) do Lighting[key] = original[key] end
  end
  if not O.time and not O.fullbright then Lighting.ClockTime = original.ClockTime end
  if not O.noFog and not O.fullbright then
    Lighting.FogEnd, Lighting.FogStart = original.FogEnd, original.FogStart
    for atmosphere, density in pairs(atmospheres) do
      if atmosphere.Parent then atmosphere.Density = density end
    end
    table.clear(atmospheres)
  end
  if not (O.fullbright or O.noFog or O.time) then original = nil end
end

-- ---------------------------------------------------------------- crosshair
local cross
-- four arms and a dot, each with a dark keyline; returns the pieces for World.styleCrosshair
function World.makeCrosshair(parent, props)
  local root = UI.frame(parent, { Name = "Crosshair", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(2, 2) })
  if props then
    for key, value in pairs(props) do root[key] = value end
  end
  local function keyline(target)
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.new(0, 0, 0)
    stroke.Transparency = 0.4
    stroke.Thickness = 1
    stroke.Parent = target
    return stroke
  end
  local arms = {}
  for index = 1, 4 do
    local arm = Instance.new("Frame")
    arm.BorderSizePixel = 0
    arm.AnchorPoint = Vector2.new(0.5, 0.5)
    arm.Parent = root
    arms[index] = { frame = arm, stroke = keyline(arm) }
  end
  local dot = Instance.new("Frame")
  dot.BorderSizePixel = 0
  dot.AnchorPoint = Vector2.new(0.5, 0.5)
  dot.Position = UDim2.fromScale(0.5, 0.5)
  UI.corner(dot, true)
  dot.Parent = root
  return { root = root, arms = arms, dot = dot, dotStroke = keyline(dot) }
end
local function buildCrosshair()
  if cross then return end
  cross = World.makeCrosshair(B.screen(8600), { Visible = false })
end
-- draws the crosshair into `cross` from the current settings; also used by the tab's preview
function World.styleCrosshair(target, o)
  local length, gap, thick = o.crossLength, o.crossGap, o.crossThickness
  local clear = 1 - o.crossOpacity / 100
  local offsets = { { 0, -(gap + length * 0.5) }, { 0, gap + length * 0.5 }, { -(gap + length * 0.5), 0 }, { gap + length * 0.5, 0 } }
  target.root.Rotation = o.crossRotation
  for index, arm in ipairs(target.arms) do
    local vertical = index <= 2
    arm.frame.Size = UDim2.fromOffset(vertical and thick or length, vertical and length or thick)
    arm.frame.Position = UDim2.new(0.5, offsets[index][1], 0.5, offsets[index][2])
    arm.frame.BackgroundColor3 = o.crossColor
    arm.frame.BackgroundTransparency = clear
    -- the first arm is the one above the centre: a T has none
    arm.frame.Visible = length > 0 and not (index == 1 and o.crossT)
    arm.stroke.Enabled = o.crossOutline
    arm.stroke.Transparency = 0.4 + 0.6 * clear
  end
  target.dot.Visible = o.crossDot
  target.dot.Size = UDim2.fromOffset(thick + 2, thick + 2)
  target.dot.BackgroundColor3 = o.crossColor
  target.dot.BackgroundTransparency = clear
  target.dotStroke.Enabled = o.crossOutline
  target.dotStroke.Transparency = 0.4 + 0.6 * clear
end
local function refreshCrosshair()
  if O.crosshair then
    buildCrosshair()
    World.styleCrosshair(cross, O)
    cross.root.Visible = true
  elseif cross then
    cross.root.Visible = false
  end
end

-- ---------------------------------------------------------------- server
function Server.rejoin()
  Window.toast({ title = "Rejoining", text = "Back in a moment.", icon = "refresh-cw" })
  task.delay(0.4, function()
    local ok, err = pcall(function()
      if #S.Players:GetPlayers() <= 1 then S.TeleportService:Teleport(game.PlaceId, B.LP)
      else S.TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, B.LP) end
    end)
    if not ok then Window.toast({ title = "Could not rejoin", text = tostring(err), icon = "triangle-alert", tone = "bad" }) end
  end)
end
function Server.hop()
  Window.toast({ title = "Looking for a server", icon = "shuffle" })
  task.spawn(B.safe("server.hop", function()
    local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&excludeFullGames=true&limit=100"
    local ok, body = pcall(function() return game:HttpGet(url) end)
    local data = ok and select(2, pcall(function() return S.HttpService:JSONDecode(body) end))
    local choices = {}
    if type(data) == "table" and type(data.data) == "table" then
      for _, server in ipairs(data.data) do
        if type(server) == "table" and server.id ~= game.JobId and (server.playing or 0) < (server.maxPlayers or 0) then choices[#choices + 1] = server end
      end
    end
    if #choices == 0 then
      Window.toast({ title = "No other server found", text = "This may be the only one open.", icon = "triangle-alert", tone = "warn" })
      return
    end
    -- any of them, or the one with the fewest people in it, or the most that still has room
    local mode = Config.get("world.hopMode")
    local pick = choices[math.random(1, #choices)]
    if mode == "empty" or mode == "full" then
      table.sort(choices, function(a, b)
        if mode == "empty" then return (a.playing or 0) < (b.playing or 0) end
        return (a.playing or 0) > (b.playing or 0)
      end)
      pick = choices[1]
    end
    Server.picked = pick
    S.TeleportService:TeleportToPlaceInstance(game.PlaceId, pick.id, B.LP)
  end))
end
function Server.copyJoin()
  local line = string.format('game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)', game.PlaceId, game.JobId)
  local ok = B.clipboard(line)
  Window.toast(ok and { title = "Join script copied", text = "Run it to land in this exact server.", icon = "clipboard", tone = "ok" }
    or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
end

World.CROSS = { "world.crossLength", "world.crossGap", "world.crossThickness", "world.crossColor", "world.crossDot", "world.crossOutline", "world.crossOpacity",
  "world.crossRotation", "world.crossT" }
function World.define()
  Config.define("world.fullbright", false)
  Config.define("world.brightValue", 2)
  Config.define("world.crossOpacity", 100)
  Config.define("world.crossRotation", 0)
  Config.define("world.crossT", false)
  Config.define("world.hopMode", "random")
  Config.define("world.noFog", false)
  Config.define("world.time", false)
  Config.define("world.timeValue", 14)
  Config.define("world.fov", false)
  Config.define("world.fovValue", 90)
  Config.define("world.zoom", false)
  Config.define("world.zoomValue", 400)
  Config.define("world.crosshair", false)
  Config.define("world.crossLength", 7)
  Config.define("world.crossGap", 4)
  Config.define("world.crossThickness", 2)
  Config.define("world.crossColor", Color3.new(1, 1, 1))
  Config.define("world.crossDot", true)
  Config.define("world.crossOutline", true)
  Config.define("world.antiAfk", true)
  Config.define("world.fpsCap", 0)
  Config.define("world.autoExec", false)
end

function World.start()
  if World.started then return end
  World.started = true
  World.define()
  O = Config.mirror({ fullbright = "world.fullbright", noFog = "world.noFog", time = "world.time", timeValue = "world.timeValue", fov = "world.fov",
    fovValue = "world.fovValue", zoom = "world.zoom", zoomValue = "world.zoomValue", crosshair = "world.crosshair", crossLength = "world.crossLength",
    crossGap = "world.crossGap", crossThickness = "world.crossThickness", crossColor = "world.crossColor", crossDot = "world.crossDot",
    crossOutline = "world.crossOutline", crossOpacity = "world.crossOpacity", crossRotation = "world.crossRotation", crossT = "world.crossT",
    brightValue = "world.brightValue", antiAfk = "world.antiAfk", fpsCap = "world.fpsCap" })
  World.options = O
  -- games rewrite lighting on their own clock: hold ours at a low rate rather than every frame
  Motion.every(applyLighting, 4, "world.lighting")
  for _, id in ipairs({ "world.fullbright", "world.noFog", "world.time" }) do
    Config.on(id, function(on) if on then applyLighting() else restoreLighting() end end)
  end
  Config.on("world.timeValue", applyLighting)
  Config.on("world.brightValue", applyLighting)

  local baseFov
  Motion.every(function()
    local camera = workspace.CurrentCamera
    if not camera then return end
    if O.fov then
      if not baseFov then baseFov = camera.FieldOfView end
      if math.abs(camera.FieldOfView - O.fovValue) > 0.05 then camera.FieldOfView = O.fovValue end
    elseif baseFov then
      camera.FieldOfView = baseFov
      baseFov = nil
    end
  end, nil, "world.fov")
  local baseZoom
  local function zoom()
    if O.zoom then
      baseZoom = baseZoom or B.LP.CameraMaxZoomDistance
      B.LP.CameraMaxZoomDistance = O.zoomValue
    elseif baseZoom then
      B.LP.CameraMaxZoomDistance = baseZoom
      baseZoom = nil
    end
  end
  Config.on("world.zoom", zoom)
  Config.on("world.zoomValue", zoom)
  zoom()

  Config.on("world.crosshair", refreshCrosshair)
  for _, id in ipairs(World.CROSS) do
    Config.on(id, refreshCrosshair)
  end
  refreshCrosshair()

  -- anti-AFK: answer the idle signal the way a player moving the mouse would
  B.connect(B.LP.Idled, function()
    if not O.antiAfk then return end
    pcall(function()
      local virtual = S.VirtualUser
      virtual:CaptureController()
      virtual:ClickButton2(Vector2.new())
    end)
  end, "world.afk")

  local function cap()
    if type(setfpscap) ~= "function" then return end
    pcall(setfpscap, O.fpsCap > 0 and O.fpsCap or 9999)
  end
  Config.on("world.fpsCap", cap)
  if O.fpsCap > 0 then cap() end

  -- carry the hub across a teleport, once per session
  local function queue()
    if World.queued or not Config.get("world.autoExec") or type(queue_on_teleport) ~= "function" then return end
    World.queued = true
    pcall(queue_on_teleport, 'pcall(function() loadstring(readfile("BasedHub.lua"))() end)')
  end
  Config.on("world.autoExec", queue)
  queue()

  B.own(function()
    O.fullbright, O.noFog, O.time = false, false, false
    restoreLighting()
    if baseFov and workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView = baseFov end
    if baseZoom then B.LP.CameraMaxZoomDistance = baseZoom end
  end)
end
end
do -- 26_flight.lua
-- ============================================================================
--  26 flight   animated flight: charge, launch, cruise, sonic boom, timed landing
--
--  Physics is the Zod project's proven arrangement: a LinearVelocity and an
--  AlignOrientation on our own root (which we own, so it replicates) with the
--  humanoid parked in a state that applies no forces of its own. The effects
--  and sounds are Zod's too (zod/src/fx.lua and its captured particle pack).
--
--  The animations are the eleven supplied clips. They are marketplace pack
--  animations, so they load in any game and replicate to everyone; they are
--  R15 only. Each was sampled on a live rig on 2026-10-07 and the numbers
--  below come from that, not from watching them:
--
--    clip        length  torso pitch         what it is
--    idle         6.33 s   +11..+17 deg      float, bobbing half a stud
--    idle2        3.48 s    +4..+7, yaw -41  side-on float
--    slow         1.08 s   -31..-35          forward-leaning glide
--    aggressive   1.85 s     0..-9           upright, arms driving
--    up           2.75 s    -4..+6           upright climb
--    upFast       0.50 s    -5..-7           rigid rocket pose
--    aimDown      1.67 s   -24               leaning in, looking down
--    sonic        0.50 s   -83               flat, head first
--    down         0.60 s   -122              head-first dive
--    charge       4.83 s   see CHARGE        crouch with a hand on the ground
--    land         2.87 s   see LAND          descend, crouch, stand, float again
--
--  The pitch already inside a clip decides how much the ROOT is tilted on top
--  of it (POSE): the flat sonic pose follows the flight path fully, the upright
--  climb not at all. Every clip is published as a loop, including the landing,
--  so the landing is played once by hand and its feet are timed to the ground.
-- ============================================================================
local S, util, Config, Assets, fs = B.S, B.util, B.Config, B.Assets, B.fs
local ease = B.Motion.ease
local UIS = S.UserInputService
local STATE = Enum.HumanoidStateType
local UP = Vector3.yAxis
local Flight = { state = "off", speed = 0, ramp = 0, charge = 0, booms = 0, landings = 0, launches = 0, boomLog = {} }
B.Flight = Flight
local O

local ANIMS = { idle = 108435473734278, idle2 = 91122978632763, idle3 = 94269438718677, idle4 = 76290458763814, slow = 76516494715741,
  aggressive = 114663559035455, up = 115265121798442, upFast = 116738664195186, aimDown = 83572938141768, sonic = 132624199623293,
  down = 120193221019191, hoverDown = 102323315718330, land = 107349693471273, charge = 89111716130280 }
Flight.ANIMS = ANIMS
-- Three clips came later and were sampled the same way (2026-10-08):
--   idle3      3.48 s  the side-on float of idle2 with the arms folded, hips 0.85 above standing
--   idle4      7.10 s  arms folded, the torso turning between 11 and 53 degrees to look about
--   hoverDown  1.00 s  upright, arms held out wide, barely moving: the easy way down
-- Hovering wears whichever of the four idles the player picks. The descend key alone, at an easy
-- pace, wears hoverDown; the head-first `down` is kept for a real dive.
local IDLES = { a = "idle", b = "idle2", c = "idle3", d = "idle4" }
local IDLE_ORDER = { "a", "b", "c", "d" }
-- follow: share of the flight path's elevation the root takes on.  lean: pitch added at speed
-- (radians, negative is forward).  rocket: stands the body's own axis along a climbing path.
-- dive: the same for a dive steeper than the clip's own.  bank: share of the turn lean rolled.
local POSE = {
  idle = { follow = 0, lean = 0, bank = 0.3 }, idle2 = { follow = 0, lean = 0, bank = 0.3 },
  idle3 = { follow = 0, lean = 0, bank = 0.3 }, idle4 = { follow = 0, lean = 0, bank = 0.3 },
  hoverDown = { follow = 0, lean = 0, bank = 0.2 },
  slow = { follow = 0.35, lean = 0, bank = 0.5 }, aggressive = { follow = 0.6, lean = -0.45, bank = 0.7 },
  aimDown = { follow = 0.5, lean = 0, bank = 0.5 }, sonic = { follow = 1, lean = 0, bank = 1 },
  up = { follow = 0, lean = 0, bank = 0.3, rocket = 0.5 }, upFast = { follow = 0, lean = 0, bank = 0.3, rocket = 1 },
  -- measured live in a straight dive at 900 st/s: at 0.5 the hips-to-head line sat 54 degrees off
  -- the path (the clip arches the head back up), so the dive takes the whole difference
  down = { follow = 0, lean = 0, bank = 0.4, dive = 1 },
}
-- The land clip, in seconds (root space, standing feet at -2.99):
--   0.00  leaning back with the feet 0.38 above the ground: the last of the descent
--   0.47  the feet reach the ground          0.68  a hand comes down beside them
--   0.78  the crouch is at its deepest       1.63  starts to stand
--   2.07  upright, feet still down           2.20  lifts off into a float again (it is a loop)
-- So it starts `lead` seconds before the ground and plays at contact/lead until the feet are
-- down, is held there until `hold`, and is faded out across the moment it stands upright.
local LAND = { lead = 0.6, contact = 0.46, hold = 1.0, out = 1.95, fade = 0.2 }
Flight.LAND = LAND
-- The charge clip stands at 0, is crouched by 0.33 s and then only breathes, with the torso at
-- its lowest at 2.25 s and 4.25 s. Turning playback around at those two still points holds the
-- crouch for as long as Space is held, and playback speed replicates where TimePosition does not.
local CHARGE = { low = 2.25, high = 4.25 }
local CLIMB_BOOST = 1.0      -- seconds of Space on a straight climb before it starts to accelerate
-- At the top of the speed range one frame is tens of studs (20,000 st/s at 240 fps is 83), and a
-- slow frame is hundreds. Two rules keep the ground solid anyway:
local HITCH = 0.05           -- speed into the ground is held to what a frame this long could cover
local PIN_SPEED = 1500       -- a landing faster than this is held on its path frame by frame
local DWELL = 0.25           -- a clip that has only just started is not swapped for its neighbour
local HOVER_DOWN_MAX = 500   -- the easy descent is only easy up to here: faster is a dive, whatever cruise is set to
local BOOM_GAP = 0.6         -- seconds between booms when a hard acceleration runs through several tiers
local SHADE = Color3.fromRGB(22, 36, 66)      -- the dark every pale image on the screen is backed with, so it shows on a bright sky
local VAPOUR = Color3.fromRGB(74, 96, 132)    -- the same idea for rings in the air: the blue-grey of vapour in shadow, not smoke
local PACK = { "SBoost", "KBoost", "STakeoff", "KTakeoff", "KSonic", "KHaze", "KCrater", "SSlam", "SImpact", "SWindTrail" }

local char, hum, root, animator
local tracks, current, currentSince = {}, nil, 0
local lv, ao, attachment
local vel, facing, lean = Vector3.zero, Vector3.new(0, 0, -1), 0
local savedAutoRotate, jumpWasEnabled
local chargeStart, chargeFx = 0, false
local spaceSince, launchUntil, launchVel = nil, 0, Vector3.zero
local stage, boomed, lastSonic, lastImpact, impact, floor = 0, 0, 0, 0, 0, nil
local airborneSince, landing, hinted, warmed = nil, nil, false, false
local idleChoice, idleIndex = { "idle" }, 1
local chargeHold
local rayParams, ignore, ignoreAt = nil, {}, -1
local tweens = {}

-- ---------------------------------------------------------------- helpers
local function alpha(rate, dt) return 1 - math.exp(-rate * dt) end
local function flat(v)
  local f = Vector3.new(v.X, 0, v.Z)
  return f.Magnitude > 1e-3 and f.Unit or nil
end
-- signed angle in degrees from one flat direction to another: a turn to the right is negative
local function signedYaw(from, to)
  local d = math.deg(math.atan2(to.X, to.Z) - math.atan2(from.X, from.Z))
  return (d + 180) % 360 - 180
end
local function alive() return hum ~= nil and root ~= nil and hum.Health > 0 and root.Parent ~= nil end
local function down(keyName) return UIS:GetFocusedTextBox() == nil and Config.keyDown(keyName) end
local function onGround()
  local state = hum:GetState()
  return hum.FloorMaterial ~= Enum.Material.Air and state ~= STATE.Freefall and state ~= STATE.Jumping and state ~= STATE.Physics
end
-- how far below the root's centre the soles are: R15 carries its leg length in HipHeight, R6 has
-- a HipHeight of 0 and two-stud legs
local function feetBelowRoot()
  local legs = 0
  if hum.RigType == Enum.HumanoidRigType.R6 then
    local leg = char:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return hum.HipHeight + root.Size.Y * 0.5 + legs
end
local function volume() return (O.sound and O.volume or 0) / 100 end
-- effects run on the real clock: the hub's own motion speed setting must not slow a shockwave
local function animate(seconds, curve, apply)
  tweens[#tweens + 1] = { t = 0, length = math.max(seconds, 1e-3), curve = curve, apply = apply }
  apply(curve(0))
end
local function stepTweens(dt)
  for index = #tweens, 1, -1 do
    local tween = tweens[index]
    tween.t += dt
    local p = math.min(tween.t / tween.length, 1)
    local ok = pcall(tween.apply, tween.curve(p))
    if p >= 1 or not ok then table.remove(tweens, index) end
  end
end
local function later(seconds, instance)
  task.delay(seconds, function() if instance.Parent then instance:Destroy() end end)
end

-- ---------------------------------------------------------------- effects (ported from zod/src/fx.lua)
local Fx = { shake = 0, shakeTime = 0, fovKick = 0, roll = 0, offset = CFrame.identity, baseFov = nil, windAcc = 0, trails = false, rings = {}, speed = 0,
  dress = 0, mach = 0, pulseAcc = 0, lineAlpha = 0, tunnelAlpha = 0, lineClock = 0, punch = 0, ripples = 0, previewUntil = 0, previewTier = 0 }
Flight.Fx = Fx
local pack, templates, folder, soundHost = nil, {}, nil, nil
local function fxFolder()
  if folder and folder.Parent then return folder end
  folder = Instance.new("Folder")
  folder.Name = util.randomName()
  folder.Parent = workspace
  B.own(folder)
  return folder
end
local function loadPack()
  if pack ~= nil then return pack end
  pack = false
  local file = Assets.manifest.fx and Assets.manifest.fx.flight
  local source = file and fs.read(fs.path(file))
  local chunk = source and loadstring(source, "=flight-pack")
  if chunk then
    local ok, result = pcall(chunk)
    if ok and type(result) == "table" then pack = result end
  end
  return pack
end
-- Potassium may write MeshPart.MeshId directly (measured); an executor that may not gets the
-- mesh the supported way, in the background, and the template simply has it from then on.
local function ensureMesh(part, id)
  if part.MeshId ~= "" then return end
  task.spawn(function()
    local ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(Content.fromUri(id)) end)
    if not ok then ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(id) end) end
    if ok and made then
      pcall(function() part:ApplyMesh(made) end)
      made:Destroy()
    end
  end)
end
-- node = { class, parentIndex, properties, attributes, references }
local function buildTemplate(nodes)
  local made = table.create(#nodes)
  for index, node in ipairs(nodes) do
    local instance = Instance.new(node[1])
    for name, value in pairs(node[3]) do pcall(function() instance[name] = value end) end
    if node[4] then
      for name, value in pairs(node[4]) do instance:SetAttribute(name, value) end
    end
    if node[1] == "MeshPart" and node[3].MeshId then ensureMesh(instance, node[3].MeshId) end
    made[index] = instance
  end
  local top
  for index, node in ipairs(nodes) do
    if node[5] then
      for property, target in pairs(node[5]) do pcall(function() made[index][property] = made[target] end) end
    end
    if node[2] == 0 then top = top or made[index] else made[index].Parent = made[node[2]] end
  end
  -- The captured pressure-wave mesh carries a red, always-on-top Highlight: on screen that is a
  -- red flash across the whole body at every boom. Nothing here wants a Highlight.
  for _, instance in ipairs(made) do
    if instance:IsA("Highlight") then instance:Destroy() end
  end
  return top
end
local function template(name)
  local cached = templates[name]
  if cached == nil then
    local data = loadPack()
    cached = data and data[name] and buildTemplate(data[name]) or false
    templates[name] = cached
  end
  return cached or nil
end
local function clone(name)
  local source = template(name)
  return source and source:Clone() or nil
end
Flight.template = template
-- Mach 1 is the sonic speed, and a tier is one doubling of it: tier 1 from Mach 1, tier 2 from
-- Mach 2, tier 3 from Mach 4, and so on. Tier 1 is the boom as it has always been. From tier 2
-- up, every tier makes the boom, and what follows the body afterwards, bigger.
local function tierOf(speed)
  local mach = speed / math.max(O.sonic, 1)
  if mach < 1 then return 0, mach end
  return math.floor(math.log(mach, 2) + 1e-6) + 1, mach
end
Flight.tierOf = tierOf
-- a child of a pack template, by path
local function piece(key, ...)
  local node = template(key)
  for _, name in ipairs({ ... }) do
    node = node and node:FindFirstChild(name)
  end
  return node
end
-- An emitter grown by `scale` and made more solid by `gain` (1 leaves it be). Each is built once
-- and handed out as copies: the tiers only ever ask for a handful of sizes.
local variants = {}
local function variant(name, emitter, scale, gain)
  local made = variants[name]
  if not made then
    made = emitter:Clone()
    local sizes = {}
    for index, point in ipairs(emitter.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    if gain ~= 1 then
      local alphas = {}
      for index, point in ipairs(emitter.Transparency.Keypoints) do
        alphas[index] = NumberSequenceKeypoint.new(point.Time, math.clamp(1 - (1 - point.Value) * gain, 0, 1))
      end
      made.Transparency = NumberSequence.new(alphas)
    end
    variants[name] = made
  end
  return made:Clone()
end
-- The pack's shock rings are additive, and measured, their textures have no alpha at all (a pale
-- ring on a black square): they light up a dark sky and cannot be seen against a bright one. So
-- each gets two twins that can: the pack's vapour ring, which does have alpha, moving exactly as
-- the shock ring does, drawn once dark a little outside it and once pale a little inside.
local function twin(name, like, scale, dark)
  local key = (dark and "shade:" or "mist:") .. name
  local made = variants[key]
  if not made then
    local ring = piece("SBoost", "Attachment", "Ring")
    if not ring then return nil end
    made = like:Clone()
    local sizes = {}
    for index, point in ipairs(like.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    made.Texture = ring.Texture
    made.LightEmission, made.LightInfluence, made.Brightness = 0, 0, 1
    made.Color = ColorSequence.new(dark and VAPOUR or Color3.new(1, 1, 1))
    made.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.18, 0.62),
      NumberSequenceKeypoint.new(0.6, 0.78), NumberSequenceKeypoint.new(1, 1) })
    made.ZOffset = dark and -0.6 or -0.3
    variants[key] = made
  end
  return made:Clone()
end
-- fire every emitter the way the source games do: after EmitDelay, for EmitDuration or EmitCount
local function emit(top, scale)
  scale = scale or 1
  for _, item in ipairs(top:IsA("ParticleEmitter") and { top } or top:GetDescendants()) do
    if item:IsA("ParticleEmitter") then
      local delay, duration = item:GetAttribute("EmitDelay") or 0, item:GetAttribute("EmitDuration") or 0
      local count = item:GetAttribute("EmitCount") or item.Rate
      local function go()
        if not item.Parent then return end
        if duration > 0 then
          item.Enabled = true
          task.delay(duration, function() if item.Parent then item.Enabled = false end end)
        else
          item:Emit(math.max(1, math.floor(count * scale + 0.5)))
        end
      end
      if delay > 0.01 then task.delay(delay, go) else go() end
    end
  end
end
local function place(model, cf)
  if model:IsA("BasePart") then
    model.CFrame = cf
    model.Anchored, model.CanCollide, model.CanQuery, model.CanTouch = true, false, false, false
  end
  model.Parent = fxFolder()
end
local function tweenSize(part, to, seconds, curve)
  local from = part.Size
  animate(seconds, curve or ease.outCubic, function(p) part.Size = from:Lerp(to, p) end)
end

-- the first four are the Zod project's own files; the ids are the ones it measured loading anywhere
local SOUNDS = {
  boom = { file = "fly_boom", fallback = 558073810 }, takeoff = { file = "fly_takeoff", fallback = 138149044086182 },
  slam = { file = "fly_land", fallback = 107674019694824 }, wind = { file = "fly_wind", fallback = 5813077875 },
  crack = { id = 92631715509459 }, thump = { id = 558073810 }, step = { id = 18782450650 },
}
local function soundId(name)
  local spec = SOUNDS[name]
  if spec.id then return "rbxassetid://" .. spec.id end
  return Assets.sound(spec.file) or ("rbxassetid://" .. spec.fallback)
end
local function sounds()
  if soundHost and soundHost.Parent then return soundHost end
  soundHost = Instance.new("Folder")
  soundHost.Name = util.randomName()
  soundHost.Parent = S.SoundService
  B.own(soundHost)
  return soundHost
end
local function play(name, scale, pitch)
  local level = volume() * (scale or 1)
  if level <= 0 then return nil end
  local sound = Instance.new("Sound")
  sound.SoundId = soundId(name)
  sound.Volume = math.min(level, 10)
  sound.PlaybackSpeed = pitch or 1
  sound.Parent = sounds()
  sound:Play()
  later(10, sound)
  Fx.lastSound = name
  return sound
end

function Fx.kick(shake, fov)
  if O.fxShake then Fx.shake = math.max(Fx.shake, shake) end
  if O.fxFov then Fx.fovKick = math.max(Fx.fovKick, fov) end
end
function Fx.takeoff(groundAt, strength)
  strength = math.clamp(strength, 0.3, 1.6)
  if O.fxTakeoff then
    for _, name in ipairs({ "KTakeoff", "STakeoff" }) do
      local burst = clone(name)
      if burst then
        place(burst, CFrame.new(groundAt))
        emit(burst, strength)
        later(6, burst)
      end
    end
  end
  play("takeoff", 1.1, 0.95 + 0.1 * strength)
  Fx.kick(0.35 * strength, 6 * strength)
end

-- Rings and bursts ride ahead of the body, square to the direction of travel. Zod could weld them
-- above the head because it laid the whole root flat; here the clip supplies the pose and the root
-- stays nearer upright, so they are re-aimed along the real path every frame instead.
local function heading()
  if Fx.previewUntil > os.clock() and Fx.previewDir then return Fx.previewDir end
  if Flight.state == "flying" and vel.Magnitude > 8 then return vel.Unit end
  return UP
end
local function frameAlong(direction, distance)
  local at = root.Position + direction * distance
  return CFrame.lookAt(at, at + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis)
end
local function ride(distance)
  local att = Instance.new("Attachment")
  att.Parent = root
  att.WorldCFrame = frameAlong(heading(), distance)
  Fx.rings[att] = distance
  return att
end
function Fx.aim()
  local direction = heading()
  for att, distance in pairs(Fx.rings) do
    if att.Parent then att.WorldCFrame = frameAlong(direction, distance) else Fx.rings[att] = nil end
  end
end
local function ringAttachment(names, enabled, distance)
  local source = template("SBoost")
  local holder = source and source:FindFirstChild("Attachment")
  if not holder or not root then return nil end
  local att = ride(distance)
  for _, name in ipairs(names) do
    local emitter = holder:FindFirstChild(name)
    if emitter then
      local copy = emitter:Clone()
      copy.Enabled = enabled
      copy.Parent = att
    end
  end
  return att
end
local function retire(att, seconds)
  for _, item in ipairs(att:GetChildren()) do
    if item:IsA("ParticleEmitter") then item.Enabled = false end
  end
  later(seconds, att)
end
function Fx.startCharge()
  if Fx.chargeAtt or not O.fxBoost then return end
  Fx.chargeAtt = ringAttachment({ "Ring", "Ring1" }, true, 3.2)
end
function Fx.stopCharge()
  local att = Fx.chargeAtt
  Fx.chargeAtt = nil
  if att then retire(att, 1) end
end
function Fx.boostRing(on)
  if on then
    if not Fx.boostAtt and O.fxBoost then Fx.boostAtt = ringAttachment({ "Ring2" }, true, 3.5) end
  elseif Fx.boostAtt then
    retire(Fx.boostAtt, 2)
    Fx.boostAtt = nil
  end
end
-- a glass shell welded to the root that swells and collapses: the pressure wave
function Fx.haze()
  local mesh = O.fxHaze and root and clone("KHaze")
  if not mesh then return end
  mesh.Anchored, mesh.CanCollide, mesh.CanQuery, mesh.CanTouch, mesh.Massless = false, false, false, false, true
  mesh.Material = Enum.Material.Glass
  mesh.Transparency = 6          -- the source game passes 6 on purpose: refraction with no fill
  mesh.Size = Vector3.new(0.2, 0.2, 0.2)
  mesh.CFrame = root.CFrame
  local weld = Instance.new("Weld")
  weld.Part0, weld.Part1 = root, mesh
  weld.Parent = mesh
  mesh.Parent = fxFolder()
  tweenSize(mesh, Vector3.new(20, 20, 20), 0.12, ease.outSine)
  task.delay(0.12, function() if mesh.Parent then tweenSize(mesh, Vector3.zero, 0.36, ease.inCubic) end end)
  later(0.6, mesh)
end
function Fx.boostStage(level)
  if not root then return end
  if O.fxBoost then
    local source = template("KBoost")
    local part = source and source:FindFirstChild("Boost" .. level)
    local holder = part and part:FindFirstChild("Attachment")
    if holder then
      local att = ride(3)
      -- an emitter's Acceleration is in world space: as captured, these gusts all blew toward
      -- +Z whichever way the flight was going. They are turned to blow back along the path.
      local back = -heading()
      for _, item in ipairs(holder:GetChildren()) do
        if item:IsA("ParticleEmitter") then
          local copy = item:Clone()
          local push = copy.Acceleration.Magnitude
          if push > 0 then copy.Acceleration = back * push end
          copy.Parent = att
        end
      end
      emit(att)
      later(3, att)
    end
    Fx.boostRing(true)
  end
  if level >= 3 then Fx.haze() end
  play("takeoff", 0.55, 1.1 + level * 0.12)
  Fx.kick(0.25 + level * 0.12, 3 + level * 2.5)
end
function Fx.sonicBoom(velocity, tier)
  if not root then return end
  local direction = velocity.Magnitude > 1 and velocity.Unit or root.CFrame.LookVector
  local over = math.clamp((tier or 1) - 1, 0, 6)      -- how far past the plain boom this one is
  if O.fxSonic then
    local att = ringAttachment({ "BigRing" }, false, 3.5)
    if att then
      local big = att:FindFirstChild("BigRing")
      if big then big:Emit(big:GetAttribute("EmitCount") or 3) end
      local source = template("SBoost")
      local vapor = source and source.Attachment:FindFirstChild("VaporCone")
      if vapor then
        local cone = Instance.new("Attachment")
        cone.CFrame = CFrame.new(0, 0, 2.5)
        cone.Parent = att
        local copy = vapor:Clone()
        copy.Enabled = true
        copy.Parent = cone
        task.delay(1, function() if copy.Parent then copy.Enabled = false end end)
      end
      later(4, att)
    end
    -- the ring left hanging in the air where the barrier broke
    local ring = clone("KSonic")
    if ring then
      place(ring, CFrame.lookAt(root.Position, root.Position + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(math.pi / 2, 0, 0))
      emit(ring)
      later(4, ring)
    end
    if over > 0 then
      -- Past Mach 2, anything left hanging in the air is behind the camera within a frame. So
      -- what grows with the speed is what travels WITH the body: shock rings that open around
      -- it one after another, each wider than the last, and a gust of wind thrown back off it.
      local rings = ride(2.5)
      local big = 1 + 0.55 * over
      for index = 1, math.min(1 + over, 5) do
        task.delay((index - 1) * 0.07, function()
          if not rings.Parent then return end
          local grown = big * (0.7 + 0.3 * index)
          for _, name in ipairs({ "Shockwave1", "Shockwave2" }) do
            local from = piece("KBoost", "Boost3", "Attachment", name)
            if from then
              local wave = variant(name .. ":" .. over .. ":" .. index, from, grown, 1)
              wave.Name = "MachRing"
              wave.Parent = rings
              wave:Emit(1)
            end
          end
          local like = piece("KBoost", "Boost3", "Attachment", "Shockwave2")
          for _, dark in ipairs({ true, false }) do
            local ring = like and twin("ring:" .. over .. ":" .. index, like, grown * (dark and 1.04 or 0.93), dark)
            if ring then
              ring.Name = dark and "MachRingShade" or "MachRingMist"
              ring.Parent = rings
              ring:Emit(1)
            end
          end
        end)
      end
      local wind = piece("KBoost", "Boost3", "Attachment", "Wind3")
      if wind then
        -- Seen live at Mach 16: seventy-odd of these at 1.6 times their opacity were a white
        -- cloud with a silhouette in it. A dozen or two, as drawn, read as wind.
        local gust = variant("gust:" .. over, wind, 1 + 0.15 * over, 1)
        gust.Name = "MachGust"
        gust.Acceleration = -direction * wind.Acceleration.Magnitude
        gust.Parent = rings
        gust:Emit(10 + 6 * over)
      end
      later(2.5, rings)
    end
  end
  Fx.haze()
  -- louder and lower the higher the tier; from Mach 2 the boom comes as the pair of bangs a real
  -- one is, and from Mach 8 there is a roll of thunder under it
  local pitch = math.max(1 - 0.06 * over, 0.64)
  play("boom", math.min(1.5 + 0.2 * over, 2.8), pitch)
  play("crack", 0.55, pitch)
  if over >= 1 then
    task.delay(0.11, function() play("boom", 1.1 + 0.15 * over, pitch * 0.82) end)
    Fx.punch = 1
  end
  if over >= 1 then Fx.ripple(tier) end
  if over >= 3 then
    play("thump", 0.9, 0.6)
    play("slam", 0.9, 0.7)
  end
  Fx.kick(math.min(1.1 + 0.3 * over, 2.6), math.min(16 + 4 * over, 36))
end
function Fx.crater(at, normal, power)
  power = math.clamp(power, 0.2, 2)
  if O.fxCrater then
    local up = normal or UP
    local cf = CFrame.lookAt(at, at + up, math.abs(up.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(-math.pi / 2, 0, 0)
    if power >= 0.45 then
      local mesh = clone("KCrater")
      if mesh then
        local full = mesh.Size
        mesh.Size = Vector3.new(full.X * 0.2, full.Y, full.Z * 0.2) * power
        place(mesh, cf + up * 0.05)
        tweenSize(mesh, full * power, 0.18, ease.outCubic)
        emit(mesh, power)
        task.delay(5, function()
          if not mesh.Parent then return end
          local skin = mesh:FindFirstChildOfClass("SurfaceAppearance")
          if skin then skin:Destroy() end      -- a SurfaceAppearance ignores the fade otherwise
          animate(1.2, ease.linear, function(p) mesh.Transparency = p end)
        end)
        later(7, mesh)
      end
    end
    -- dust for every landing; the full slam ring only for the heavy ones
    local dust = clone(power >= 0.9 and "SSlam" or "STakeoff")
    if dust then
      place(dust, power >= 0.9 and cf or CFrame.new(at))
      emit(dust, math.clamp(power, 0.35, 1.4))
      later(5, dust)
    end
  end
  if power >= 0.9 then
    play("slam", 1.4)
    play("thump", 0.7)
  else
    play("step", 0.5 + power * 0.6)
  end
  Fx.kick(0.4 + 0.6 * power, 7 * power)
end
function Fx.wall(at, normal)
  if O.fxCrater then
    local mark = clone("SImpact")
    if mark then
      local size = mark.Size
      mark.Size = Vector3.new(0.1, 0.1, 0.1)
      place(mark, CFrame.lookAt(at, at + normal, math.abs(normal.Y) < 0.95 and UP or Vector3.xAxis))
      tweenSize(mark, size, 0.2)
      for _, item in ipairs(mark:GetDescendants()) do
        if item:IsA("ParticleEmitter") then item:Emit(item.Rate) end
      end
      later(5, mark)
    end
  end
  play("slam", 1.1)
  Fx.kick(0.9, 10)
end
local LIMBS = { "RightHand", "LeftHand", "RightFoot", "LeftFoot" }
-- limb trails last longer and show more the higher the tier
local function styleTrail(trail)
  local over = math.clamp(Fx.dress - 1, 0, 5)
  trail.Lifetime = 0.13 * (1 + 0.6 * over)
  trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.93 - 0.07 * over), NumberSequenceKeypoint.new(1, 1) })
end
function Fx.setTrails(on)
  on = on == true
  if on == Fx.trails or not char then return end
  Fx.trails = on
  local proto = on and template("SWindTrail")
  proto = proto and proto:FindFirstChildWhichIsA("Trail")
  for _, name in ipairs(LIMBS) do
    local limb = char:FindFirstChild(name)
    if limb then
      local a, b = limb:FindFirstChild("BasedTrailA"), limb:FindFirstChild("BasedTrailB")
      if on and not a and proto then
        a, b = Instance.new("Attachment"), Instance.new("Attachment")
        a.Name, b.Name = "BasedTrailA", "BasedTrailB"
        local half = limb.Size.X / 1.7 * 2
        a.CFrame, b.CFrame = CFrame.new(half, 0, 0), CFrame.new(-half, 0, 0)
        a.Parent, b.Parent = limb, limb
        local trail = proto:Clone()
        trail.Attachment0, trail.Attachment1 = a, b
        trail.Color = ColorSequence.new(O.trailColor)
        styleTrail(trail)
        trail.Enabled = true
        trail.Parent = a
      elseif not on and a then
        local trail = a:FindFirstChildWhichIsA("Trail")
        if trail then trail.Enabled = false end
        a.Name = "BasedTrailDone"
        if b then b.Name = "BasedTrailDone"; later(0.6, b) end
        later(0.6, a)
      end
    end
  end
end
-- Wind streaks: two points a hair apart with a trail between them, carried for a tenth of a
-- second and then let go, so each draws a line as long as that tenth of a second of flight. They
-- are pooled: the top tiers throw ninety a second, and making three instances for every one of
-- them is the kind of churn that shows up as a stutter.
local streaks, streakFree = {}, {}
Fx.streaks = streaks
local function windStreak()
  local terrain = workspace:FindFirstChildOfClass("Terrain")
  if not root or not terrain then return end
  local streak = table.remove(streakFree)
  if not streak then
    local proto = template("SWindTrail")
    proto = proto and proto:FindFirstChildWhichIsA("Trail")
    if not proto or #streaks >= 140 then return end
    local a, b = Instance.new("Attachment"), Instance.new("Attachment")
    local trail = proto:Clone()
    trail.Attachment0, trail.Attachment1 = a, b
    trail.Color = ColorSequence.new(Color3.new(1, 1, 1))
    trail.Parent = a
    streak = { a = a, b = b, trail = trail }
    streaks[#streaks + 1] = streak
  end
  local a, b, trail = streak.a, streak.b, streak.trail
  local over = math.clamp(Fx.dress - 1, 0, 4)
  local reach = 10 + 3 * over
  local offset = Vector3.new(math.random(-100, 100), math.random(-100, 100), math.random(-100, 100)) / 100 * reach
  trail.Enabled = false
  a.Parent, b.Parent = root, root
  a.Position, b.Position = offset, offset + Vector3.new(0.06 + 0.03 * over, 0, 0)
  trail.Lifetime = 0.13 * (1 + 0.5 * over)
  trail:Clear()
  trail.Enabled = true
  -- let go of it after a moment, so the streak stretches out behind us
  task.delay(0.1, function()
    if not a.Parent or not b.Parent then return end
    local at, bt = a.WorldPosition, b.WorldPosition
    a.Parent, b.Parent = terrain, terrain
    a.WorldPosition, b.WorldPosition = at, bt
  end)
  task.delay(0.25 + trail.Lifetime, function()
    if a.Parent and b.Parent then
      streakFree[#streakFree + 1] = streak
    else
      -- its points went with a body that was replaced: forget it
      local at = table.find(streaks, streak)
      if at then table.remove(streaks, at) end
    end
  end)
end
-- What follows the body while it stays fast, from Mach 2 up: a vapour cone at the nose sized to
-- the tier, a shock ring thrown off it at intervals from Mach 4, and a glow there from Mach 8.
-- All of it rides with the body, for the reason given at the boom.
local function dressTo(tier)
  if tier == Fx.dress then return end
  Fx.dress = tier
  if Fx.dressAtt then
    retire(Fx.dressAtt, 0.6)
    Fx.dressAtt, Fx.pulse, Fx.pulseTwins = nil, nil, nil
  end
  if tier >= 2 and O.fxSonic and root and root.Parent then
    local over = math.min(tier - 1, 6)
    -- Ahead of the body, and further ahead the bigger it is. Seen on screen at Mach 32 with the
    -- cone a stud and a half off the chest: its vapour drifts back, and from the chase camera
    -- there was a white cloud where the body should be. Out in front, the body is drawn over it.
    local att = ride(4 + 0.6 * over)
    local vapor = piece("SBoost", "Attachment", "VaporCone")
    if vapor then
      local cone = variant("cone:" .. over, vapor, 1 + 0.2 * over, 1)
      cone.Name = "MachCone"
      cone.Enabled = true
      cone.Parent = att
    end
    local shock = tier >= 3 and piece("KBoost", "Boost3", "Attachment", "Shockwave2")
    if shock then
      Fx.pulse = variant("pulse:" .. over, shock, 0.9 + 0.35 * over, 0.85)
      Fx.pulse.Name = "MachPulse"
      Fx.pulse.Parent = att
      Fx.pulseTwins = {}
      for _, dark in ipairs({ true, false }) do
        local ring = twin("pulse:" .. over, shock, (0.9 + 0.35 * over) * (dark and 1.04 or 0.93), dark)
        if ring then
          ring.Name = dark and "MachPulseShade" or "MachPulseMist"
          ring.Parent = att
          Fx.pulseTwins[#Fx.pulseTwins + 1] = ring
        end
      end
    end
    local glowId = tier >= 4 and Assets.image("glow")
    if glowId then
      -- Air piled up white-hot ahead of the body: a rim of light round the head and shoulders
      -- as seen from behind. Small and faint on purpose. The first version (eleven studs wide,
      -- four deep) was measured on screen as a fog that left only a silhouette.
      local glow = Instance.new("ParticleEmitter")
      glow.Name = "BowGlow"
      glow.Texture = glowId
      glow.Rate, glow.Lifetime, glow.Speed = 16, NumberRange.new(0.1, 0.14), NumberRange.new(0, 0)
      glow.Size = NumberSequence.new(2.6 + 0.35 * over)
      glow.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.3, 0.9), NumberSequenceKeypoint.new(1, 1) })
      glow.Color = ColorSequence.new(Color3.fromRGB(214, 230, 255))
      glow.LightEmission, glow.LightInfluence, glow.LockedToPart, glow.ZOffset = 1, 0, true, 1
      glow.Parent = att
    end
    Fx.dressAtt = att
  end
  if char then
    for _, name in ipairs(LIMBS) do
      local limb = char:FindFirstChild(name)
      local a = limb and limb:FindFirstChild("BasedTrailA")
      local trail = a and a:FindFirstChildWhichIsA("Trail")
      if trail then styleTrail(trail) end
    end
  end
end
-- What is drawn over the game past Mach 2. All of it is images, so it costs nothing in the world:
--   speed lines   streaks at the edge of the screen that point at its centre, redrawn at a new
--                 angle some twenty times a second, with a second set between them from Mach 8
--   the tunnel    the edges of the screen darken, deeper with every doubling
--   the ripple    at each boom, a shock ring opens across the screen from the body
-- Measured on a pale sky, white alone could hardly be seen. So everything pale has the same
-- image in dark blue under it, a hair larger or turned a fraction: one of the two always shows.
local overlays, lines, lineShade, lines2, tunnel
local function overlay(name, image, z, tint)
  if not overlays or not overlays.Parent then overlays = B.screen(7900) end
  local label = Instance.new("ImageLabel")
  label.Name = name
  label.BackgroundTransparency = 1
  label.Image = image
  label.ImageColor3 = tint or Color3.new(1, 1, 1)
  label.AnchorPoint, label.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
  label.ImageTransparency = 1
  label.Visible = false
  label.ZIndex = z
  label.Parent = overlays
  return label
end
function Fx.ripple(tier)
  local id = O.fxLines and Assets.image("shock")
  local camera = workspace.CurrentCamera
  if not id or not camera or not root then return end
  Fx.ripples += 1
  local over = math.clamp(tier - 1, 1, 6)
  local at, seen = camera:WorldToViewportPoint(root.Position)
  local centre = seen and UDim2.fromOffset(at.X, at.Y) or UDim2.fromScale(0.5, 0.5)
  local reach = camera.ViewportSize.Magnitude * (1.5 + 0.12 * over)       -- how wide it ends, in pixels
  local strength = math.min(0.55 + 0.08 * over, 0.9)
  -- one ring at Mach 2, two from Mach 4, three from Mach 16
  for index = 1, over >= 4 and 3 or (over >= 2 and 2 or 1) do
    task.delay((index - 1) * 0.09, function()
      local dark, light = overlay("ScreenShockShade", id, 5, SHADE), overlay("ScreenShock", id, 6)
      dark.Position, light.Position = centre, centre
      dark.Visible, light.Visible = true, true
      animate(0.36 + 0.05 * over, ease.outCubic, function(p)
        local side = (0.05 + 0.95 * p) * reach
        light.Size = UDim2.fromOffset(side, side)
        dark.Size = UDim2.fromOffset(side * 1.03, side * 1.03)
        local left = (1 - p) ^ 1.4 * strength
        light.ImageTransparency = 1 - left
        dark.ImageTransparency = 1 - left * 0.85
      end)
      later(1.5, dark)
      later(1.5, light)
    end)
  end
end
local function speedLines(dt, mach, active)
  local want, dark = 0, 0
  if O.fxLines then
    if active then want = math.clamp((mach - 1.6) / 5, 0, 1) * 0.5 end
    if active then dark = math.clamp(math.log(math.max(mach, 1), 2) - 1, 0, 3) / 3 * 0.42 end
    Fx.punch = math.max(0, Fx.punch - dt * 2.5)
    want = math.min(want + Fx.punch * 0.35, 0.8)
    dark = math.min(dark + Fx.punch * 0.2, 0.6)
  else
    Fx.punch = 0
  end
  Fx.lineAlpha += (want - Fx.lineAlpha) * alpha(7, dt)
  Fx.tunnelAlpha += (dark - Fx.tunnelAlpha) * alpha(5, dt)
  if Fx.tunnelAlpha < 0.004 then
    if tunnel and tunnel.Visible then tunnel.Visible = false end
  else
    local id = not tunnel and Assets.image("vignette")
    if id then
      tunnel = overlay("MachTunnel", id, 1)
      tunnel.Size = UDim2.fromScale(1, 1)
    end
    if tunnel then
      tunnel.Visible = true
      tunnel.ImageTransparency = 1 - Fx.tunnelAlpha
    end
  end
  if Fx.lineAlpha < 0.004 then
    if lines and lines.Visible then lines.Visible, lineShade.Visible, lines2.Visible = false, false, false end
    return
  end
  if not lines then
    local id = Assets.image("speedlines")
    if not id then return end
    lineShade, lines2, lines = overlay("SpeedShade", id, 2, SHADE), overlay("SpeedLines2", id, 3), overlay("SpeedLines", id, 4)
    Fx.lines = lines
  end
  if not lines.Visible then
    -- a square that still covers the screen whichever way it is turned
    local side = math.ceil(workspace.CurrentCamera.ViewportSize.Magnitude * 1.08)
    lines.Size = UDim2.fromOffset(side, side)
    lineShade.Size, lines2.Size = lines.Size, lines.Size
    lines.Visible, lineShade.Visible, lines2.Visible = true, true, true
  end
  lines.ImageTransparency = 1 - Fx.lineAlpha
  lineShade.ImageTransparency = 1 - Fx.lineAlpha * 0.9
  lines2.ImageTransparency = 1 - Fx.lineAlpha * math.clamp((mach - 8) / 24, 0, 1) * 0.9
  Fx.lineClock += dt
  if Fx.lineClock >= 0.045 then
    Fx.lineClock = 0
    lines.Rotation = math.random(0, 359)
    lineShade.Rotation = lines.Rotation + 0.35      -- beside each line, not under it
    lines2.Rotation = math.random(0, 359)
  end
end
-- every frame: the dressing, trails, streaks and the wind loop all follow real speed
function Fx.update(dt, speed, flying, boosting)
  Fx.speed, Fx.flying, Fx.boosting = speed, flying, boosting
  local previewing = Fx.previewUntil > os.clock()
  local tier, mach = 0, 0
  if previewing then
    tier, mach = Fx.previewTier, 2 ^ (Fx.previewTier - 1) * 1.2
  elseif flying then
    tier, mach = tierOf(speed)
  end
  Fx.mach = mach
  -- up a tier the moment it is reached, down only once the speed is well under it
  if tier > Fx.dress then
    dressTo(tier)
  elseif Fx.dress > 0 and (previewing or not flying or speed < O.sonic * 2 ^ (Fx.dress - 1) * 0.85) then
    dressTo(tier)
  end
  if Fx.pulse and Fx.pulse.Parent then
    Fx.pulseAcc += dt
    if Fx.pulseAcc >= math.clamp(0.95 - 0.12 * Fx.dress, 0.3, 0.7) then
      Fx.pulseAcc = 0
      Fx.pulse:Emit(1)
      for _, ring in ipairs(Fx.pulseTwins or {}) do ring:Emit(1) end
    end
  end
  speedLines(dt, mach, flying or previewing)
  if not flying and not Fx.trails and not Fx.wind then return end
  local cruise = O.speed
  Fx.setTrails(flying and O.fxTrails and speed > math.max(60, cruise * 0.45))
  if flying and O.fxStreaks and speed > math.max(cruise * 1.1, 100) then
    Fx.windAcc += dt
    local every = math.clamp(0.05 - (speed - cruise) / 20000, Fx.dress >= 3 and 0.011 or 0.02, 0.05)
    while Fx.windAcc >= every do
      Fx.windAcc -= every
      windStreak()
    end
  else
    Fx.windAcc = 0
  end
  local wind = Fx.wind
  if wind and wind.Parent then
    local charging = Flight.state == "charging"
    local target = (flying and math.clamp(speed / 300, 0, 3) * 0.5 or (charging and 0.25 + 0.3 * Flight.charge or 0)) * volume()
    wind.Volume += (target - wind.Volume) * alpha(8, dt)
    local pitch = charging and (0.6 + 0.9 * Flight.charge) or math.clamp(speed / 165, 0.75, 2)
    wind.PlaybackSpeed += (pitch - wind.PlaybackSpeed) * alpha(8, dt)
    if target > 0.01 and not wind.IsPlaying then wind:Play()
    elseif target <= 0.01 and wind.Volume < 0.01 and wind.IsPlaying then wind:Stop() end
  end
end
local function cameraUndo()
  local camera = workspace.CurrentCamera
  if camera and Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
  Fx.offset = CFrame.identity
end
local function cameraApply(dt)
  local camera = workspace.CurrentCamera
  if not camera or not O then return end
  dt = math.min(dt, 0.1)
  Fx.shakeTime += dt
  Fx.shake = math.max(0, Fx.shake - dt * 1.6)
  Fx.fovKick = math.max(0, Fx.fovKick - dt * 22)
  -- the camera rolls a few degrees the way the body banks
  Fx.roll += ((Fx.flying and O.fxShake and math.clamp(lean * 0.12, -8, 8) or 0) - Fx.roll) * alpha(4, dt)
  local amp = 0
  if Fx.flying and O.fxShake and Fx.speed > 5 then
    amp = math.clamp(Fx.speed / 900, 0, 0.55) * (Fx.boosting and 1.2 or 1) + 0.07 * math.clamp(Fx.dress - 1, 0, 5)
  end
  amp += Fx.shake * 2
  if amp > 1e-4 or math.abs(Fx.roll) > 0.01 then
    local t = Fx.shakeTime * 4.4 * math.pi
    local offset = CFrame.Angles(math.sin(t) * amp * 0.004 + math.sin(t * 3.1) * Fx.shake * 0.01,
      math.sin(t * 0.7 + 1.3) * amp * 0.003 + math.cos(t * 2.7) * Fx.shake * 0.01, math.sin(t * 0.5 + 2.7) * amp * 0.002 + math.rad(Fx.roll))
    camera.CFrame = camera.CFrame * offset
    Fx.offset = offset
  end
  -- the field of view widens with speed, unless the player has locked it in Visuals
  if O.fxFov and not Config.get("world.fov") and (Fx.flying or Fx.fovKick > 0 or Fx.baseFov) then
    Fx.baseFov = Fx.baseFov or camera.FieldOfView
    local want = Fx.baseFov + (Fx.flying and math.clamp(Fx.speed * 15 / 450, 0, 32) or 0)
    want = math.min(want + Fx.fovKick, 115)
    camera.FieldOfView += (want - camera.FieldOfView) * alpha(4, dt)
    if not Fx.flying and Fx.fovKick <= 0 and math.abs(camera.FieldOfView - Fx.baseFov) < 0.05 then
      camera.FieldOfView = Fx.baseFov
      Fx.baseFov = nil
    end
  elseif Fx.baseFov then
    camera.FieldOfView = Fx.baseFov
    Fx.baseFov = nil
  end
end
-- build the templates a frame apart and fetch their textures and the sounds, so the first
-- boom is not a silent, untextured one
local function warm()
  if warmed then return end
  warmed = true
  task.spawn(function()
    local list = {}
    for _, name in ipairs(PACK) do
      local made = template(name)
      if made then list[#list + 1] = made end
      task.wait()
    end
    local wind = Instance.new("Sound")
    wind.SoundId = soundId("wind")
    wind.Looped = true
    wind.Volume = 0
    wind.Parent = sounds()
    Fx.wind = wind
    for name in pairs(SOUNDS) do
      if name ~= "wind" then
        local sound = Instance.new("Sound")
        sound.SoundId = soundId(name)
        sound.Parent = sounds()
        list[#list + 1] = sound
        later(20, sound)
      end
    end
    pcall(function() S.ContentProvider:PreloadAsync(list) end)
  end)
end
-- Fire the boom of a tier where the body stands, and wear that tier for a moment: what a setting
-- looks like, without having to fly it. The rings open along the way the body faces.
function Fx.preview(tier)
  if not root or not root.Parent then return false end
  warm()
  local look = root.CFrame.LookVector
  Fx.previewTier, Fx.previewUntil, Fx.previewDir = tier, os.clock() + 2.6, look
  Fx.sonicBoom(look * O.sonic * 2 ^ (tier - 1), tier)
  return true
end

-- ---------------------------------------------------------------- animation layer
local function loadTracks()
  table.clear(tracks)
  current, Flight.clip = nil, nil
  Flight.animated = false
  if not animator or not O.animations or hum.RigType ~= Enum.HumanoidRigType.R15 then return end
  local preload = {}
  for name, id in pairs(ANIMS) do
    local animation = Instance.new("Animation")
    animation.AnimationId = "rbxassetid://" .. id
    local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
    if ok and track then
      -- three of the clips are published at Core priority and would lose to the game's own idle
      track.Priority = Enum.AnimationPriority.Action4
      tracks[name] = track
      preload[#preload + 1] = animation
      Flight.animated = true
    end
  end
  -- fetched before first use: a track played before its data arrives shows nothing to anyone
  task.spawn(function() pcall(function() S.ContentProvider:PreloadAsync(preload) end) end)
end
local function setAnim(name, fade, rate)
  Flight.clip = name
  local track = tracks[name]
  if not track then
    -- no clip for this (R6, or animations off): make sure nothing stale keeps playing
    if current and tracks[current] then tracks[current]:Stop(fade or 0.25) end
    current = nil
    return
  end
  if current == name then
    if rate and math.abs(track.Speed - rate) > 0.04 then track:AdjustSpeed(rate) end
    return
  end
  local previous = current and tracks[current]
  track:Play(fade or 0.3, 1, rate or 1)
  if previous then previous:Stop(fade or 0.3) end
  current, currentSince = name, os.clock()
end
local function stopAnims(fade)
  for _, track in pairs(tracks) do
    if track.IsPlaying then track:Stop(fade or 0.25) end
  end
  current, Flight.clip = nil, nil
end
-- the hover poses the player picked, in a fixed order, and the one whose turn it is
local function chooseIdles(list)
  table.clear(idleChoice)
  for _, key in ipairs(IDLE_ORDER) do
    if table.find(list, key) then idleChoice[#idleChoice + 1] = IDLES[key] end
  end
  if #idleChoice == 0 then idleChoice[1] = "idle" end
end
local function idleName() return idleChoice[(idleIndex - 1) % #idleChoice + 1] end
local function isIdle(name) return name == "idle" or name == "idle2" or name == "idle3" or name == "idle4" end
-- playback speed follows airspeed; stepped, because every change is sent to the other clients
local function paced(base, gain, fraction, low, high)
  return math.floor(math.clamp(base + gain * fraction, low, high) * 20 + 0.5) / 20
end

-- ---------------------------------------------------------------- physics
local function buildPhysics()
  if lv and lv.Parent and ao and ao.Parent then return end
  for _, item in ipairs({ lv, ao, attachment }) do
    if item then pcall(function() item:Destroy() end) end
  end
  attachment = Instance.new("Attachment")
  attachment.Name = util.randomName()
  attachment.Parent = root
  lv = Instance.new("LinearVelocity")
  lv.Attachment0 = attachment
  lv.MaxForce = math.huge
  lv.RelativeTo = Enum.ActuatorRelativeTo.World
  lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
  lv.VectorVelocity = vel
  lv.Parent = root
  ao = Instance.new("AlignOrientation")
  ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
  ao.Attachment0 = attachment
  ao.MaxTorque = math.huge
  ao.MaxAngularVelocity = math.huge
  ao.Responsiveness = 14
  ao.CFrame = root.CFrame.Rotation
  ao.Parent = root
end
local function teardownPhysics()
  for _, item in ipairs({ lv, ao, attachment }) do
    if item then pcall(function() item:Destroy() end) end
  end
  lv, ao, attachment = nil, nil, nil
end
-- Space charges a launch while flight is armed, so it must not also jump
local function blockJump(block)
  if not hum then return end
  if block then
    if jumpWasEnabled == nil then
      jumpWasEnabled = hum:GetStateEnabled(STATE.Jumping)
      hum:SetStateEnabled(STATE.Jumping, false)
    end
  elseif jumpWasEnabled ~= nil then
    pcall(function() hum:SetStateEnabled(STATE.Jumping, jumpWasEnabled) end)
    jumpWasEnabled = nil
  end
end
-- Physics: the humanoid applies no forces of its own. Freefall: Roblox's own character sounds,
-- which run on every client for every character, play a rushing-wind loop from the replicated
-- state, which makes the wind the one sound other players hear.
local function flightState() return O.windForOthers and STATE.Freefall or STATE.Physics end

local function startFlying(initial)
  if not alive() or Flight.state == "flying" then return end
  Flight.state = "flying"
  vel = initial or root.AssemblyLinearVelocity
  Flight.ramp, stage, lean, spaceSince, boomed, impact, floor = 0, 0, 0, nil, 0, 0, nil
  facing = flat(root.CFrame.LookVector) or facing
  buildPhysics()
  if savedAutoRotate == nil then savedAutoRotate = hum.AutoRotate end
  hum.AutoRotate = false
  hum:ChangeState(flightState())
  blockJump(true)
end
-- hand the body back to the humanoid; `toGround` when we are standing on something
local function leaveFlight(toGround)
  Fx.stopCharge()
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp = 0, 0
  local momentum = root and root.Parent and root.AssemblyLinearVelocity or Vector3.zero
  teardownPhysics()
  if hum and savedAutoRotate ~= nil then
    pcall(function() hum.AutoRotate = savedAutoRotate end)
    savedAutoRotate = nil
  end
  if alive() then
    if toGround then
      hum:ChangeState(STATE.GettingUp)
    else
      -- keep the momentum and let the humanoid fall normally
      hum:ChangeState(STATE.Freefall)
      root.AssemblyLinearVelocity = momentum
    end
  end
end
local function stopEverything()
  local state = Flight.state
  if state == "flying" or (state == "landing" and lv ~= nil) then leaveFlight(false) end
  Fx.stopCharge()
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  stopAnims(0.25)
  blockJump(false)
  landing, airborneSince = nil, nil
  Flight.state, Flight.speed, Flight.ramp, Flight.charge = "off", 0, 0, 0
end

-- ---------------------------------------------------------------- the ground
local function exclusions()
  local now = os.clock()
  if now - ignoreAt > 0.5 then
    ignoreAt = now
    table.clear(ignore)
    if folder then ignore[#ignore + 1] = folder end
    -- never land on, or crash into, another player
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player.Character then ignore[#ignore + 1] = player.Character end
    end
    rayParams.FilterDescendantsInstances = ignore
  end
  return rayParams
end
local function groundBelow(from, reach)
  local hit = workspace:Raycast(from, Vector3.new(0, -reach, 0), exclusions())
  if hit and hit.Normal.Y > 0.55 then return hit end
  return nil
end

-- ---------------------------------------------------------------- charge and launch
-- While charging the body is held where it stands: the crouch has a hand on the ground, and
-- walking slides it along (in the first minutes of real use the player held W through four
-- charges out of five). Sideways only; up and down are left to the ground.
local function holdStill(on)
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  if not on or not root or not root.Parent then return end
  local att = Instance.new("Attachment")
  att.Name = util.randomName()
  att.Parent = root
  local plane = Instance.new("LinearVelocity")
  plane.Attachment0 = att
  plane.MaxForce = math.huge
  plane.RelativeTo = Enum.ActuatorRelativeTo.World
  plane.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
  plane.PrimaryTangentAxis, plane.SecondaryTangentAxis = Vector3.xAxis, Vector3.zAxis
  plane.PlaneVelocity = Vector2.zero
  plane.Parent = root
  chargeHold = { att = att, plane = plane }
end
local function beginCharge()
  Flight.state, Flight.charge = "charging", 0
  chargeStart, chargeFx = os.clock(), false
  holdStill(true)
  setAnim("charge", 0.15, 1)
end
local function release()
  local held = os.clock() - chargeStart
  Fx.stopCharge()
  holdStill(false)
  local charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  local quick = held < 0.2
  local strength = quick and 0.4 or (0.6 + charge)
  local up = quick and 46 or O.launch * (0.5 + 0.9 * charge)
  local forward = (flat(workspace.CurrentCamera.CFrame.LookVector) or Vector3.zero) * up * 0.12
  local hit = groundBelow(root.Position, 12)
  Fx.takeoff(hit and hit.Position + Vector3.new(0, 0.1, 0) or root.Position - Vector3.new(0, feetBelowRoot(), 0), strength)
  Flight.state, Flight.charge = "ground", 0
  Flight.launches += 1
  launchVel = UP * up + forward
  -- the launch carries for a moment whatever the keys say: it boosts up to the sky
  launchUntil = os.clock() + (quick and 0.25 or 0.45 + 0.75 * charge)
  startFlying(launchVel)
  setAnim(quick and "up" or "upFast", 0.12, 1)
end
local function stepCharge()
  local held = os.clock() - chargeStart
  Flight.charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  if held > 0.2 then
    if not chargeFx then
      chargeFx = true
      Fx.startCharge()
    end
    Fx.kick(0.05 + 0.1 * Flight.charge, 0)
  end
  local track = tracks.charge
  if track and track.IsPlaying then
    local at = track.TimePosition
    if at >= CHARGE.high and track.Speed > 0 then track:AdjustSpeed(-1)
    elseif at <= CHARGE.low and track.Speed < 0 then track:AdjustSpeed(1) end
  end
  if not down("Space") then
    release()
  elseif not onGround() then
    -- knocked off the ground while charging: let go of the crouch, the armed state catches the fall
    Fx.stopCharge()
    holdStill(false)
    stopAnims(0.15)
    Flight.state, Flight.charge = "ground", 0
  end
end

-- ---------------------------------------------------------------- landing
local function beginLanding(hit, approach)
  local feet = feetBelowRoot()
  landing = { started = os.clock(), from = root.Position, to = hit.Position + UP * feet, ground = hit.Position, normal = hit.Normal,
    power = math.clamp(approach / 320, 0.25, 1.8), approach = approach, touched = false, released = false,
    look = flat(vel) or flat(root.CFrame.LookVector) or facing }
  Flight.state = "landing"
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp, spaceSince = 0, 0, nil
  -- measured live: in Freefall the humanoid flickers into Landed over the last studs, at full
  -- descent speed, which is exactly what a game's fall damage listens for. Physics has no Landed.
  hum:ChangeState(STATE.Physics)
  -- slowed so that the clip's feet reach the ground on the frame the body does
  setAnim("land", 0.18, LAND.contact / LAND.lead)
end
-- The way down: sideways motion is shed along the way, the drop itself is not eased (the crouch
-- is what absorbs it). Returns where the root should be at `t` and how fast it is moving there.
local function landingPath(L, t)
  local p = math.clamp(t / LAND.lead, 0, 1)
  local span = L.to - L.from
  local across, rate = 1 - (1 - p) ^ 2, 2 * (1 - p) / LAND.lead
  return Vector3.new(L.from.X + span.X * across, L.from.Y + span.Y * p, L.from.Z + span.Z * across),
    Vector3.new(span.X * rate, span.Y / LAND.lead, span.Z * rate)
end
local function finishLanding(fade)
  local track = tracks.land
  if track and track.IsPlaying then track:Stop(fade) end
  if lv then leaveFlight(true) end
  current, Flight.clip = nil, nil
  landing = nil
  Flight.state = "ground"
end
local function touchDown(L)
  L.touched, L.touchedAt = true, os.clock()
  local feet = feetBelowRoot()
  -- Measured live: a landing from 5,665 st/s was abandoned because the body was more than six
  -- studs from its mark, which at that speed is a quarter of one frame. Only a body that stopped
  -- SHORT of the mark, by more than a tenth of a second of travel, met something on the way; one
  -- that is level with it or past it (a slow frame carries it on) simply belongs on the mark.
  local span = L.to - L.from
  local past = span.Magnitude > 1e-3 and (root.Position - L.to):Dot(span.Unit) or 0
  if past < 0 and (root.Position - L.to).Magnitude > math.max(6, L.approach * 0.12) then
    -- something stood in the way: put down here if there is ground here, otherwise carry on flying
    local below = groundBelow(root.Position, feet + 4)
    if not below then
      landing = nil
      Flight.state = "flying"
      vel = Vector3.zero
      return
    end
    L.to, L.ground, L.normal = below.Position + UP * feet, below.Position, below.Normal
  end
  vel = Vector3.zero
  if lv then lv.VectorVelocity = vel end
  root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = vel, vel
  root.CFrame = CFrame.lookAt(L.to, L.to + L.look)
  if ao then
    ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
    ao.Responsiveness = 60
  end
  local track = tracks.land
  if track then track:AdjustSpeed(1) end
  Flight.landings += 1
  Fx.crater(L.ground, L.normal, L.power)
end
local function stepLanding(dt)
  local L = landing
  local now = os.clock()
  if not L.touched then
    local t = now - L.started
    -- the last frame of travel is taken by the touchdown itself: one more frame at this
    -- velocity would carry the body past the ground before anything could stop it
    if t + dt < LAND.lead and lv and lv.Parent then
      if hum:GetState() ~= STATE.Physics then hum:ChangeState(STATE.Physics) end
      -- The path's own velocity with a gentle pull back onto it. Chasing the position frame by
      -- frame was measured live to swing between 4 and 250 st/s on a 120 st/s descent (frames
      -- and physics steps do not line up); this is the same path, flown smoothly.
      local point, speed = landingPath(L, t)
      local off = point - root.Position
      if L.approach > PIN_SPEED and off.Magnitude > 1 then
        -- at thousands of studs a second that same mismatch is tens of studs: put the body on
        -- the path. A correction of less than one frame's travel cannot be told from the travel.
        root.CFrame = root.CFrame.Rotation + point
        off = Vector3.zero
      end
      vel = speed + off * 6
      lv.VectorVelocity = vel
      ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
      ao.Responsiveness = 30
      return
    end
    touchDown(L)
    if landing ~= L then return end
  end
  local clipTime = LAND.contact + (now - L.touchedAt)
  if not tracks.land then
    if now - L.touchedAt > 0.25 then finishLanding(0) end
    return
  end
  if not L.released and clipTime >= LAND.hold then
    -- the body was held still through the impact; from here the humanoid has it again
    L.released = true
    leaveFlight(true)
  end
  if clipTime >= LAND.out then
    finishLanding(LAND.fade)
  elseif L.released and (hum.MoveDirection.Magnitude > 0.1 or down("Space")) then
    finishLanding(0.3)
  end
end

-- ---------------------------------------------------------------- flying
local function direction(camera)
  local move = UIS:GetFocusedTextBox() and Vector3.zero or hum.MoveDirection
  local dir = Vector3.zero
  if move.Magnitude > 0.01 then
    -- the flat move direction becomes camera-relative in 3D: look up while pressing forward, fly up
    local basis = CFrame.lookAt(Vector3.zero, flat(camera.CFrame.LookVector) or Vector3.new(0, 0, -1))
    dir = camera.CFrame:VectorToWorldSpace(basis:VectorToObjectSpace(move))
  end
  local vertical = (down("Space") and 1 or 0) - (down(O.keyDown) and 1 or 0)
  local horizontal = dir.Magnitude > 0.01
  if vertical ~= 0 then dir += UP * vertical * (horizontal and 0.7 or 1) end
  return dir.Magnitude > 0.01 and dir.Unit or Vector3.zero, vertical, horizontal
end
-- which clip, and how fast it plays. Every threshold is wider on the way out than on the way
-- in, so a speed sitting on one does not flicker between two poses.
local function pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  local cruise, was = O.speed, current
  if launching then return "upFast", 1 end
  if not moving then
    -- a long hover moves on to the next of the chosen poses
    if O.idleEvery > 0 and #idleChoice > 1 and isIdle(was) and os.clock() - currentSince > O.idleEvery then idleIndex += 1 end
    return idleName(), 1
  end
  local fraction = speed / math.max(cruise, 1)
  local climbing = was == "up" or was == "upFast"
  if (vertical > 0 and not horizontal) or elevation > (climbing and 0.8 or 0.95) then
    if heldUp > CLIMB_BOOST + 0.1 or speed > cruise * (was == "upFast" and 1.4 or 1.7) then return "upFast", 1 end
    return "up", paced(0.8, 0.5, fraction, 0.8, 1.5)
  end
  if (vertical < 0 and not horizontal) or elevation < ((was == "down" or was == "hoverDown") and -0.75 or -0.9) then
    -- hovering down is the descend key on its own at an easy pace; boosted, steered into or simply fast, it is the dive
    local easy = math.min(math.max(cruise * 1.35, 60), HOVER_DOWN_MAX) * (was == "hoverDown" and 1.2 or 1)
    if vertical < 0 and not horizontal and Flight.ramp < 0.05 and speed <= easy then return "hoverDown", 1 end
    return "down", 1
  end
  if speed >= O.sonic * (was == "sonic" and 0.6 or 0.72) then return "sonic", 1 end
  if Flight.ramp > 0.1 or speed > cruise * (was == "aggressive" and 1.25 or 1.5) then
    return "aggressive", paced(0.9, 0.5, speed / math.max(O.top, 1), 0.9, 1.5)
  end
  if elevation < (was == "aimDown" and -0.28 or -0.38) then return "aimDown", 1 end
  return "slow", paced(0.7, 0.6, fraction, 0.7, 1.4)
end
local function stepFly(dt)
  local camera = workspace.CurrentCamera
  local want = flightState()
  if hum:GetState() ~= want then hum:ChangeState(want) end
  buildPhysics()
  local now = os.clock()
  local dir, vertical, horizontal = direction(camera)
  local moving = dir.Magnitude > 0
  local launching = launchUntil > now
  -- how long Space has been held: a long hold on a straight climb becomes the run at the boom
  if vertical > 0 then spaceSince = spaceSince or now else spaceSince = nil end
  local heldUp = spaceSince and now - spaceSince or 0

  local boosting = moving and (down(O.keyBoost) or (vertical > 0 and not horizontal and heldUp > CLIMB_BOOST))
  local ramp = Flight.ramp
  if boosting then ramp = math.min(1, ramp + dt / math.max(O.rampTime, 0.3)) else ramp = math.max(0, ramp - dt / 0.8) end
  Flight.ramp = ramp
  local wantStage = ramp >= 0.999 and 3 or (ramp >= 0.6 and 2 or (ramp >= 0.2 and 1 or 0))
  if wantStage > stage then
    stage = wantStage
    Fx.boostStage(stage)
  elseif wantStage < stage then
    stage = wantStage
    if stage == 0 then Fx.boostRing(false) end
  end

  local cruise = O.speed
  local top = math.max(O.top, cruise)
  local target = launching and launchVel or (moving and dir * (cruise + (top - cruise) * ramp ^ 1.5) or Vector3.zero)
  vel = vel:Lerp(target, alpha(launching and 10 or (moving and 4 + 2 * ramp or 5), dt))
  lv.VectorVelocity = vel
  local speed = vel.Magnitude
  Flight.speed = speed

  -- The boom, on the speed the body really has. Each tier booms once on the way up and is armed
  -- again when the speed is back under 80% of where it starts. A hard acceleration that runs
  -- through several tiers inside BOOM_GAP booms once more, for the highest one it has reached.
  local real = root.AssemblyLinearVelocity.Magnitude
  local tier = tierOf(real)
  if tier > boomed and now - lastSonic > (boomed == 0 and 1.35 or BOOM_GAP) then
    boomed, lastSonic = tier, now
    Flight.booms += 1
    Flight.boomLog[#Flight.boomLog + 1] = tier
    if #Flight.boomLog > 40 then table.remove(Flight.boomLog, 1) end
    Fx.sonicBoom(vel, tier)
  else
    while boomed > 0 and real < O.sonic * 2 ^ (boomed - 1) * 0.8 do boomed -= 1 end
  end

  local elevation = speed > 4 and math.asin(math.clamp(vel.Y / speed, -1, 1)) or 0
  local name, rate = pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  if current and POSE[current] and name ~= current and now - currentSince < DWELL then name, rate = current, nil end
  if isIdle(current) and not isIdle(name) then idleIndex += 1 end
  setAnim(name, (name == "sonic" or name == "upFast") and 0.2 or (isIdle(name) and (isIdle(current) and 0.6 or 0.4) or 0.3), rate)

  -- orientation: face along the path, tilt by what the clip does not already supply, bank into turns
  local planar = Vector3.new(vel.X, 0, vel.Z)
  local planarSpeed = planar.Magnitude
  if (moving or launching) and planarSpeed > math.max(6, speed * 0.2) then facing = planar.Unit end
  local wantLean = 0
  local dirFlat = flat(dir)
  if moving and dirFlat and planarSpeed > 20 then wantLean = math.clamp(signedYaw(planar.Unit, dirFlat) * 1.3, -70, 70) end
  lean += (wantLean - lean) * alpha(5, dt)
  local base = CFrame.lookAt(Vector3.zero, facing)
  local pitch, roll
  if not moving and not launching then
    -- hovering or braking: upright, tipped a little the way it is still drifting
    local drift = base:VectorToObjectSpace(vel)
    pitch, roll = math.clamp(drift.Z / 200, -0.25, 0.25), math.clamp(-drift.X / 200, -0.25, 0.25)
    ao.Responsiveness = 18
  else
    local blend = math.clamp(speed / math.max(cruise * 0.7, 30), 0, 1)
    local pose = tracks[name] and POSE[name]
    if pose then
      pitch = elevation * pose.follow + pose.lean
      if pose.rocket then pitch += (math.max(elevation, 0.6) - math.pi / 2) * pose.rocket end
      if pose.dive and elevation < -0.56 then pitch += (elevation + 0.56) * pose.dive end
    else
      -- no clip to wear (R6, animations off, or it failed to load): the body itself leads, head first
      pitch = elevation - math.pi / 2
    end
    pitch *= blend
    roll = math.rad(lean) * (pose and pose.bank or 1) * blend
    ao.Responsiveness = 14
  end
  -- rolled about the direction of travel first, then pitched: a bank stays a bank at any pitch
  ao.CFrame = base * CFrame.Angles(0, 0, roll) * CFrame.Angles(pitch, 0, 0)

  -- the ground: a landing is timed from the moment the path is sure to meet it. Measured: a ray
  -- finds nothing further than 15,000 studs however long it is asked to be, so this look-ahead
  -- (0.6 s of descent) sees the whole approach up to about 25,000 st/s straight down. Faster
  -- than that the landing starts when the ground comes into view and takes its 0.6 s from there.
  if O.autoLand and not launching then
    local descent = math.max(-vel.Y, 0)
    local slope = speed > 1 and vel.Y / speed or 0
    if vertical < 0 or (descent > 4 and (slope < -0.5 or (speed >= 320 and slope < -0.2))) then
      local feet = feetBelowRoot()
      local hit = groundBelow(root.Position, feet + descent * LAND.lead + 6)
      local clearance = hit and root.Position.Y - hit.Position.Y - feet
      -- Coming down at the ground is only a landing while it is still being flown there, or when
      -- it is too late to stop. With the keys let go the body brakes inside descent / 5 studs, and
      -- letting go high above the ground used to be taken for a landing anyway.
      local meant = vertical < 0 or (moving and dir.Y < -0.2) or (hit ~= nil and descent / 5 > clearance)
      if hit and meant and clearance <= descent * LAND.lead + (vertical < 0 and 4.5 or 0.5) then
        -- where the path meets the ground, not the spot straight below
        local carry = planar * LAND.lead * 0.5
        local there = carry.Magnitude > 1 and groundBelow(root.Position + carry + UP * 2, clearance + feet + 16) or hit
        if there and carry.Magnitude > 1 then
          local blocked = workspace:Raycast(root.Position, there.Position + UP * feet - root.Position, exclusions())
          if blocked and (blocked.Position - there.Position).Magnitude > 1.5 then there = hit end
        end
        if there then
          beginLanding(there, speed)
          return
        end
      end
    end
  end
  -- Something solid in the next frame's path. A wall at speed cracks and throws us back. Ground
  -- we are not landing on lets the feet come down onto it and no further: at these speeds a body
  -- covers several studs between physics steps and would otherwise pass clean through a floor,
  -- and at any speed it would sink to its waist. So a low pass skims the ground on its feet.
  local solid = not Config.get("move.noclip")
  if speed > 20 and solid then
    local heading = vel.Unit
    local feet = feetBelowRoot()
    local travel = math.max(speed * dt * 1.6, 4)
    local hit = workspace:Raycast(root.Position, heading * (math.max(speed * HITCH, travel) + feet * math.max(-heading.Y, 0)), exclusions())
    if hit and hit.Normal.Y > 0.55 then
      -- the speed into the ground is held to what one slow frame could cover, so the body
      -- flares onto its feet instead of arriving in a single step that might go through
      local gap = math.max((root.Position - hit.Position):Dot(hit.Normal) - feet, 0)
      local into = -vel:Dot(hit.Normal)
      if into > gap / HITCH then
        impact = math.max(impact, into)
        vel += hit.Normal * (into - gap / HITCH)
        lv.VectorVelocity = vel
        if gap < 2 and impact > 250 and now - lastImpact > 1 then
          lastImpact = now
          Fx.crater(hit.Position, hit.Normal, math.clamp(impact / 320, 0.6, 1.8))
          impact = 0
        end
      else
        impact = 0
      end
      floor = floor or {}
      floor.at, floor.normal, floor.seen = hit.Position, hit.Normal, now
    elseif hit and speed > 320 and hit.Distance <= travel + 2 then
      Fx.wall(hit.Position, hit.Normal)
      vel = hit.Normal * 25
      lv.VectorVelocity = vel
      Flight.ramp, stage = 0, 0
      Fx.boostRing(false)
    end
  end
  -- A frame longer than HITCH can still leave the body under the ground it was coming down on,
  -- where no ray ahead will ever find that ground again. If the surface last seen is now above
  -- the body, put the body back on it.
  if floor and solid and now - floor.seen < 0.5 then
    local feet = feetBelowRoot()
    local height = (root.Position - floor.at):Dot(floor.normal)
    if height < feet - 0.75 then
      local over = workspace:Raycast(root.Position + floor.normal * (feet - height + 2), -floor.normal * (feet - height + 2), exclusions())
      if over and over.Normal.Y > 0.55 then
        root.CFrame += over.Normal * (feet - (root.Position - over.Position):Dot(over.Normal))
        local into = -vel:Dot(over.Normal)
        if into > 0 then
          vel += over.Normal * into
          lv.VectorVelocity = vel
        end
        floor.at, floor.normal, floor.seen = over.Position, over.Normal, now
      end
    end
  end
end

local function step(dt)
  stepTweens(dt)
  if not O.fly or not alive() or hum.SeatPart then
    if Flight.state ~= "off" then stopEverything() end
    if Fx.previewUntil > os.clock() and alive() then Fx.aim() end
    Fx.update(dt, 0, false, false)
    return
  end
  dt = math.min(dt, 0.1)
  warm()
  local state = Flight.state
  if state == "off" then
    if onGround() then
      Flight.state = "ground"
      blockJump(true)
      if not hinted and B.Window and B.Window.toast then
        hinted = true
        B.Window.toast({ title = "Flight is armed", text = "Hold Space to charge, let go to launch.", icon = "plane", time = 4.5 })
      end
    else
      startFlying()
    end
  elseif state == "ground" then
    blockJump(true)
    if onGround() then
      airborneSince = nil
      if down("Space") then beginCharge() end
    else
      -- walked off an edge, or knocked into the air: catch it
      airborneSince = airborneSince or os.clock()
      if os.clock() - airborneSince > 0.25 then
        airborneSince = nil
        startFlying()
      end
    end
  elseif state == "charging" then
    stepCharge()
  elseif state == "flying" then
    stepFly(dt)
  elseif state == "landing" then
    stepLanding(dt)
  end
  Fx.aim()
  Fx.update(dt, root.AssemblyLinearVelocity.Magnitude, Flight.state == "flying", stage > 0)
end

local function attach(character)
  pcall(stopEverything)
  teardownPhysics()
  table.clear(Fx.rings)
  table.clear(streaks)
  table.clear(streakFree)
  Fx.trails, Fx.chargeAtt, Fx.boostAtt, Fx.dressAtt, Fx.pulse, Fx.pulseTwins, Fx.dress, Fx.previewUntil = false, nil, nil, nil, nil, nil, 0, 0
  savedAutoRotate, jumpWasEnabled = nil, nil
  char, hum, root, animator = nil, nil, nil, nil
  table.clear(tracks)
  if not character then return end
  local humanoid = character:WaitForChild("Humanoid", 8)
  local rootPart = character:WaitForChild("HumanoidRootPart", 8)
  if not humanoid or not rootPart or B.LP.Character ~= character then return end
  char, hum, root = character, humanoid, rootPart
  animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 4)
  loadTracks()
end

-- what the Movement tab shows while this is running
function Flight.status()
  local state = Flight.state
  if state == "flying" then
    local speed = root and root.Parent and root.AssemblyLinearVelocity.Magnitude or Flight.speed
    local tier, mach = tierOf(speed)
    return (tier > 0 and string.format("Mach %.1f", mach) or (stage > 0 and "Boosting" or (speed < 8 and "Hovering" or "Flying"))), speed, mach
  elseif state == "charging" then
    return "Charging " .. math.floor(Flight.charge * 100 + 0.5) .. "%", 0
  elseif state == "landing" then
    return "Landing", 0
  elseif state == "ground" then
    return "Armed: hold Space", 0
  end
  return O.fly and "Waiting for your character" or "Off", 0
end

function Flight.define()
  Config.define("move.fly", false)
  Config.define("move.flySpeed", 120)
  Config.define("fly.top", 900)
  Config.define("fly.sonic", 650)
  Config.define("fly.rampTime", 3)
  Config.define("fly.launch", 320)
  Config.define("fly.chargeTime", 1.2)
  Config.define("fly.idles", { "a" })
  Config.define("fly.idleEvery", 0)
  -- one hover pose used to be a single choice ("a", "b" or "alternate"): carry it over, once
  local legacy = Config.define("fly.idle", "a")
  if legacy ~= "a" and Config.isDefault("fly.idles") then
    Config.set("fly.idles", legacy == "alternate" and { "a", "b" } or { legacy })
    Config.set("fly.idle", "a")
  end
  Config.define("fly.animations", true)
  Config.define("fly.autoLand", true)
  Config.define("fly.windForOthers", true)
  Config.define("fly.effects", { "sonic", "takeoff", "boost", "trails", "streaks", "haze", "crater", "shake", "fov", "lines" })
  Config.define("fly.trailColor", Color3.fromRGB(225, 230, 240))
  Config.define("fly.sound", true)
  Config.define("fly.volume", 85)
  Config.define("fly.key.boost", "LeftShift")
  Config.define("fly.key.down", "LeftControl")
end

function Flight.start()
  if Flight.started then return end
  Flight.started = true
  Flight.define()
  O = Config.mirror({ fly = "move.fly", speed = "move.flySpeed", top = "fly.top", sonic = "fly.sonic", rampTime = "fly.rampTime", launch = "fly.launch",
    chargeTime = "fly.chargeTime", idleEvery = "fly.idleEvery", animations = "fly.animations", autoLand = "fly.autoLand", windForOthers = "fly.windForOthers",
    trailColor = "fly.trailColor", sound = "fly.sound", volume = "fly.volume", keyBoost = "fly.key.boost", keyDown = "fly.key.down" })
  Flight.options = O
  local function effects(list)
    for _, name in ipairs({ "Sonic", "Takeoff", "Boost", "Trails", "Streaks", "Haze", "Crater", "Shake", "Fov", "Lines" }) do
      O["fx" .. name] = table.find(list, string.lower(name)) ~= nil
    end
  end
  effects(Config.get("fly.effects"))
  Config.on("fly.effects", effects)
  chooseIdles(Config.get("fly.idles"))
  Config.on("fly.idles", chooseIdles)
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  rayParams.RespectCanCollide = true      -- invisible trigger volumes are not ground

  B.connect(B.LP.CharacterAdded, attach, "flight.character")
  if B.LP.Character then task.spawn(B.safe("flight.attach", attach), B.LP.Character) end
  Config.on("fly.animations", function()
    if not hum then return end
    stopAnims(0.2)
    loadTracks()
  end)
  Config.on("fly.trailColor", function(color)
    if not char then return end
    for _, item in ipairs(char:GetDescendants()) do
      if item:IsA("Trail") and item.Parent and item.Parent.Name == "BasedTrailA" then item.Color = ColorSequence.new(color) end
    end
  end)
  B.connect(S.RunService.Heartbeat, function(dt)
    local ok, err = pcall(step, dt)
    if not ok then
      -- a fault here must never leave the body stuck in the air
      B.fault("flight", err)
      pcall(stopEverything)
      pcall(teardownPhysics)
      Config.set("move.fly", false)
    end
  end, "flight.step")
  S.RunService:BindToRenderStep("BasedFlightUndo", Enum.RenderPriority.Camera.Value - 1, cameraUndo)
  S.RunService:BindToRenderStep("BasedFlightApply", Enum.RenderPriority.Camera.Value + 1, function(dt) pcall(cameraApply, dt) end)
  B.own(function()
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightUndo") end)
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightApply") end)
    pcall(stopEverything)
    pcall(teardownPhysics)
    local camera = workspace.CurrentCamera
    if camera then
      if Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
      if Fx.baseFov then camera.FieldOfView = Fx.baseFov end
    end
    for _, track in pairs(tracks) do pcall(function() track:Stop(0) end) end
    for _, streak in ipairs(streaks) do
      pcall(function() streak.a:Destroy() end)
      pcall(function() streak.b:Destroy() end)
    end
    if char then
      for _, item in ipairs(char:GetDescendants()) do
        if item.Name == "BasedTrailA" or item.Name == "BasedTrailB" or item.Name == "BasedTrailDone" then pcall(function() item:Destroy() end) end
      end
    end
    for att in pairs(Fx.rings) do pcall(function() att:Destroy() end) end
  end)
end
end
do -- 27_void.lua
-- ============================================================================
--  27 void     the void cannot kill, and a fall into it is brought back
--
--  Measured on the client with throwaway parts (2026-10-07, a place whose height
--  was -500): an unanchored body under workspace.FallenPartsDestroyHeight is
--  removed by this client within half a second, an anchored one is not. Writing
--  -math.huge or -1e9 reads back -50,000: the engine clamps it, and the void is
--  simply 50,000 studs down, which is under three seconds away at flight speeds.
--  NaN is kept as written, and then nothing is removed at any depth, down to 1e12.
--  So the height is set to NaN, set again if the game changes it, and given back
--  on switch-off and on unload.
--
--  That removes the engine's void. A game whose own server script kills below
--  some height is out of reach from here. What can be done about those is not to
--  arrive: a fall with nothing under it is put back where the body last stood,
--  before it gets that far. Flight is never interfered with.
-- ============================================================================
local S, Config = B.S, B.Config
local Void = { rescues = 0, spots = {} }
B.Void = Void
local O
local NAN = 0 / 0
local AIR = Enum.Material.Air
local STATE = Enum.HumanoidStateType
local SETTLE = 0.4        -- seconds stood on a spot before it is somewhere to go back to
local APART = 10          -- studs between the spots that are remembered
local KEEP = 8
local SEE = 15000         -- a ray finds nothing further away than this (measured for the flight)
local EVERY = 0.06        -- seconds between looks: a fall is slow next to a frame

local spots = Void.spots
local gameHeight          -- the game's own height: the last value seen there that was not ours
local params
local clock, stoodSince, fallTop = 0, nil, nil
local lastRescue, lastOver, lastToast, nowhere = -math.huge, -math.huge, -math.huge, -math.huge
local wasAlive, lastY, warned, stopped = false, 0, false, false

local function unset(value) return value ~= value end      -- NaN is the one number that is not itself
local function apply()
  if stopped then return end
  local height = workspace.FallenPartsDestroyHeight
  if O.noVoid then
    if not unset(height) then
      gameHeight = height
      workspace.FallenPartsDestroyHeight = NAN
    end
  elseif gameHeight ~= nil and unset(height) then
    workspace.FallenPartsDestroyHeight = gameHeight
  end
  Void.height = gameHeight
end

local function toast(title, text)
  local now = os.clock()
  if now - lastToast < 6 or not (B.Window and B.Window.toast) then return end
  lastToast = now
  B.Window.toast({ title = title, text = text, icon = "shield", time = 3.5 })
end
local function flying()
  local state = B.Flight and B.Flight.state
  return state == "flying" or state == "landing" or state == "charging"
end
local function below(from, reach, character)
  params.FilterDescendantsInstances = { character }
  return workspace:Raycast(from, Vector3.new(0, -reach, 0), params)
end
local function soles(character, humanoid, root)
  local legs = 0
  if humanoid.RigType == Enum.HumanoidRigType.R6 then
    local leg = character:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return humanoid.HipHeight + root.Size.Y * 0.5 + legs
end

-- Somewhere to go back to: ground the body has stood on for a moment, that is part of the map
-- (anchored, or terrain) rather than something loose or carried along.
local function remember(character, humanoid, root, now)
  stoodSince = stoodSince or now
  if now - stoodSince < SETTLE then return end
  local hit = below(root.Position, soles(character, humanoid, root) + 4, character)
  local ground = hit and hit.Instance
  if not ground or not ground:IsA("BasePart") or not (ground:IsA("Terrain") or ground.Anchored) then return end
  local newest = spots[#spots]
  if newest and (newest.Position - root.Position).Magnitude < APART then
    spots[#spots] = root.CFrame
  else
    spots[#spots + 1] = root.CFrame
    if #spots > KEEP then table.remove(spots, 1) end
  end
end
local function rescue(character, root, now)
  -- back in the void this soon after the last time: that spot was no good, use the one before
  if now - lastRescue < 4 and #spots > 1 then table.remove(spots) end
  while #spots > 0 do
    local spot = spots[#spots]
    if below(spot.Position + Vector3.new(0, 2, 0), 14, character) then
      root.CFrame = spot + Vector3.new(0, 0.5, 0)
      root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
      lastRescue, fallTop = now, nil
      Void.rescues += 1
      toast("Back from the void", "Put back where you last stood.")
      return true
    end
    table.remove(spots)      -- the ground there has gone
  end
  return false
end

local function look(now)
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and character:FindFirstChild("HumanoidRootPart")
  local alive = humanoid ~= nil and root ~= nil and humanoid.Health > 0
  if not alive then
    -- It died with the void switched off, over nothing or under the game's height: the game has
    -- a rule of its own down there. Say so once, rather than leave it looking broken.
    if wasAlive and O.noVoid and not warned and (now - lastOver < 1.5 or (gameHeight ~= nil and lastY < gameHeight + 20)) then
      warned = true
      lastToast = -math.huge
      toast("This game has its own void", "Its scripts kill down there, which cannot be stopped from here. A shorter Catch me after gets you back before it.")
    end
    wasAlive, stoodSince, fallTop = false, nil, nil
    return
  end
  wasAlive, lastY = true, root.Position.Y
  if not O.noVoid then
    stoodSince, fallTop = nil, nil
    return
  end
  local state = humanoid:GetState()
  local airborne = humanoid.FloorMaterial == AIR
  if flying() or humanoid.SeatPart or state == STATE.Swimming or state == STATE.Climbing then
    stoodSince, fallTop = nil, nil
    return
  end
  if not airborne and state ~= STATE.Freefall then
    fallTop = nil
    remember(character, humanoid, root, now)
    return
  end
  stoodSince = nil
  local y = root.Position.Y
  fallTop = math.max(fallTop or y, y)              -- the highest point of this fall
  local caught = gameHeight ~= nil and y < gameHeight          -- where the game itself would have ended it
  if not caught and root.AssemblyLinearVelocity.Y < -4 and fallTop - y > 30 then
    -- falling, and some way into it: is there anything down there at all?
    if not below(root.Position, SEE, character) then
      lastOver = now
      caught = fallTop - y > O.voidDrop
    end
  end
  if caught and O.voidRescue and now >= nowhere and not rescue(character, root, now) then
    nowhere = now + 8
    toast("Nowhere to put you back", "No ground you stood on is left. The void still cannot kill you: fly out of it.")
  end
end

function Void.define()
  Config.define("move.noVoid", true)
  Config.define("move.voidRescue", true)
  Config.define("move.voidDrop", 150)
end

function Void.start()
  if Void.started then return end
  Void.started = true
  Void.define()
  O = Config.mirror({ noVoid = "move.noVoid", voidRescue = "move.voidRescue", voidDrop = "move.voidDrop" })
  Void.options = O
  params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.RespectCanCollide = true        -- something that cannot be stood on is not ground
  params.IgnoreWater = false             -- water is somewhere to land
  Config.on("move.noVoid", apply)
  -- the game setting its height again must not bring the void back
  B.connect(workspace:GetPropertyChangedSignal("FallenPartsDestroyHeight"), apply, "void.height")
  apply()
  B.connect(S.RunService.Heartbeat, function(dt)
    clock += dt
    if clock < EVERY then return end
    clock = 0
    look(os.clock())
  end, "void.look")
  B.own(function()
    -- stopped first: giving the height back fires the signal above, which would take it away again
    stopped = true
    if gameHeight ~= nil and unset(workspace.FallenPartsDestroyHeight) then workspace.FallenPartsDestroyHeight = gameHeight end
  end)
end
end
do -- 40_universal.lua
-- ============================================================================
--  40 universal  the tabs every game gets: Combat, Visuals, Movement, Players, World
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local Roster, Esp, Aim, Move, World, Server, Hud = B.Roster, B.Esp, B.Aim, B.Move, B.World, B.Server, B.Hud
local UIS = S.UserInputService
B.pages = B.pages or {}
local GROUP = "Universal"

local function onPage(id) return Window.open and Window.current ~= nil and Window.current.id == id end

-- ---------------------------------------------------------------- the 3D preview
-- Your own character on a turntable, with the real ESP renderer drawing over it.
-- Every switch in the tab changes this picture as you flip it.
local function dummy()
  local model = Instance.new("Model")
  local function block(name, size, position, color)
    local part = Instance.new("Part")
    part.Name = name
    part.Size = size
    part.CFrame = CFrame.new(position)
    part.Anchored = true
    part.Color = color
    part.Material = Enum.Material.SmoothPlastic
    part.TopSurface, part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
    part.Parent = model
    return part
  end
  local skin, shirt, trousers = Color3.fromRGB(226, 198, 170), Color3.fromRGB(96, 88, 150), Color3.fromRGB(44, 44, 54)
  block("Head", Vector3.new(1.2, 1.2, 1.2), Vector3.new(0, 4.6, 0), skin)
  local torso = block("Torso", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  block("Left Arm", Vector3.new(1, 2, 1), Vector3.new(-1.5, 3, 0), skin)
  block("Right Arm", Vector3.new(1, 2, 1), Vector3.new(1.5, 3, 0), skin)
  block("Left Leg", Vector3.new(1, 2, 1), Vector3.new(-0.5, 1, 0), trousers)
  block("Right Leg", Vector3.new(1, 2, 1), Vector3.new(0.5, 1, 0), trousers)
  local root = block("HumanoidRootPart", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  root.Transparency = 1
  model.PrimaryPart = torso
  return model
end
local function cloneCharacter()
  local character = B.character()
  if not character or not character:FindFirstChild("HumanoidRootPart") then return nil end
  local ok, clone = pcall(function()
    local archivable = character.Archivable
    character.Archivable = true
    local copy = character:Clone()
    character.Archivable = archivable
    return copy
  end)
  if not ok or not clone then return nil end
  for _, item in ipairs(clone:GetDescendants()) do
    if item:IsA("LuaSourceContainer") or item:IsA("Sound") or item:IsA("BillboardGui") or item:IsA("ForceField") or item:IsA("ParticleEmitter") or item:IsA("Tool") then
      item:Destroy()
    elseif item:IsA("BasePart") then
      item.Anchored = true
    end
  end
  local humanoid = clone:FindFirstChildOfClass("Humanoid")
  if humanoid then
    humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
  end
  clone:PivotTo(CFrame.new(0, 3, 0))
  return clone
end

local function preview(frame)
  local stage = UI.frame(frame, { Name = "Stage", Size = UDim2.new(1, -24, 1, -24), Position = UDim2.fromOffset(12, 0), ClipsDescendants = true,
    Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 0.965 })
  UI.corner(stage, "rControl")
  UI.gradient(stage, { Rotation = 90, Transparency = UI.alphaSeq(0, 1, 1, 0.9) })
  local viewport = UI.new("ViewportFrame", { Name = "Model", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, LightColor = Color3.new(1, 1, 1),
    Ambient = Color3.fromRGB(150, 150, 160), LightDirection = Vector3.new(-0.6, -1, -0.8), Parent = stage })
  local world = Instance.new("WorldModel")
  world.Parent = viewport
  local model = cloneCharacter() or dummy()
  model.Parent = world
  local camera = Instance.new("Camera")
  camera.FieldOfView = 30
  camera.Parent = viewport
  viewport.CurrentCamera = camera
  local overlay = UI.frame(stage, { Name = "Overlay", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local sample = Esp.Object.new(overlay)
  local arrow = UI.image(overlay, "arrow", { Size = UDim2.fromOffset(18, 18), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -26, 0, 30), Rotation = 55, Visible = false })
  local hint = UI.text(stage, "drag to turn", "mono", "faint", { TextSize = 10, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -8), ZIndex = 3 })

  local entry = Roster.describe(model)
  local centre = (entry.root and entry.root.Position or Vector3.new(0, 3, 0)) + Vector3.new(0, 0.25, 0)
  local yaw, spin, idle = 0.5, 0, 0
  local dragging = false
  local grab = UI.new("TextButton", { Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = stage })
  local lastX
  UI.drag(grab, function(point) dragging = true; lastX = point.X; hint.Visible = false end, function(point)
    local dx = point.X - lastX
    lastX = point.X
    yaw -= dx * 0.012
    spin = -dx * 0.012 / math.max(Motion.dt, 1 / 240)
  end, function() dragging = false; idle = 0 end)

  local info = { joints = {} }
  local joints = {}
  local clock = 0
  Motion.every(function(dt)
    if not stage.Parent or not onPage("visuals") then return end
    clock += dt
    if not dragging then
      -- a flick keeps turning and eases out; left alone, it drifts round slowly
      spin *= math.exp(-dt * 3.2)
      idle += dt
      yaw += spin * dt + (idle > 1.4 and 0.38 * dt or 0)
    end
    local size = stage.AbsoluteSize / UI.unit()
    if size.X < 10 then return end
    local distance = 15.5
    local cf = CFrame.new(centre) * CFrame.Angles(0, yaw, 0) * CFrame.new(0, 0, distance)
    camera.CFrame = cf
    local tanHalf = math.tan(math.rad(camera.FieldOfView) * 0.5)
    local aspect = size.X / size.Y
    local function project(point)
      local p = cf:PointToObjectSpace(point)
      local depth = -p.Z
      return (0.5 + p.X / (depth * tanHalf * aspect) * 0.5) * size.X, (0.5 - p.Y / (depth * tanHalf) * 0.5) * size.Y, depth
    end
    local o, on = Esp.options, Esp.want
    local head, root = entry.head, entry.root
    if not root then return end
    local _, topY = project((head and head.Position or root.Position + Vector3.new(0, 1.6, 0)) + Vector3.new(0, 0.85, 0))
    local cx, bottomY = project(root.Position - Vector3.new(0, entry.legs or 3, 0))
    local height = bottomY - topY
    local width = height * 0.56
    info.x, info.y, info.w, info.h = cx - width * 0.5, topY, width, height
    info.color = o.colorMode == "health" and Color3.fromHSV(0.33 * (0.55 + 0.45 * math.sin(clock * 0.9)), 0.75, 1) or o.color
    info.alpha = 1
    info.name = o.displayNames and B.LP.DisplayName or B.LP.Name
    info.distance = 128
    info.health = 0.55 + 0.45 * math.sin(clock * 0.9)
    info.hp = info.health * 100
    info.team = "Red team"
    info.tool = "Classic Sword"
    info.joints, info.bones, info.headR, info.lookX, info.originX = nil, nil, nil, nil, nil
    if head then
      local hx, hy, depth = project(head.Position)
      info.headX, info.headY = hx, hy
      info.headR = (head.Size.Y * 0.62) / depth * size.Y / (2 * tanHalf)
      local lx, ly = project(head.Position + head.CFrame.LookVector * 2.2)
      info.lookX, info.lookY = lx, ly
    end
    for name, part in pairs(entry.joints) do
      local jx, jy, depth = project(part.Position)
      local slot = joints[name]
      if not slot then slot = {}; joints[name] = slot end
      slot[1], slot[2], slot[3] = jx, jy, depth > 0
    end
    info.joints, info.bones = joints, entry.bones
    info.originX, info.originY = size.X * 0.5, size.Y
    sample:draw(info, o, on)
    arrow.Visible = on.arrows == true
    arrow.ImageColor3 = info.color
    -- chams cannot draw inside a viewport: tint the model the way the fill would
    local fill = on.chams and (1 - o.chamsFill / 100) or 0
    viewport.ImageColor3 = Color3.new(1, 1, 1):Lerp(info.color, fill * 0.85)
  end, nil, "esp.preview")
end

-- ---------------------------------------------------------------- Visuals
-- the last stop of a distance slider reads as no limit rather than as a number
local function reach(limit)
  return function(v) return v >= limit and "No limit" or (util.comma(v) .. " st") end
end
B.pages[#B.pages + 1] = function()
  Esp.start(); World.start()
  Window.page({ id = "visuals", title = "Visuals", icon = "eye", group = GROUP, order = 220, build = function(page)
    local show = page:section({ title = "Preview", icon = "scan-eye", column = 1, weight = 8 })
    show:custom({ height = 348, build = preview })
    show:toggle({ id = "esp.enabled", label = "Player ESP", desc = "Draws the picture above on every player." })

    local what = page:section({ title = "What to draw", icon = "layers", column = 2, weight = 5 })
    what:multi({ id = "esp.elements", label = "Elements", empty = "Nothing", menuWidth = 226, options = {
      { "box", "Box", icon = "scan" }, { "name", "Name", icon = "tag" }, { "health", "Health bar", icon = "heart-pulse" }, { "hp", "Health number", icon = "hash" },
      { "distance", "Distance", icon = "ruler" }, { "tool", "Held tool", icon = "sword" }, { "team", "Team name", icon = "flag" }, { "skeleton", "Skeleton", icon = "bone" },
      { "head", "Head ring", icon = "circle" }, { "look", "Look direction", icon = "navigation" }, { "tracer", "Tracer", icon = "route" },
      { "arrows", "Off-screen arrows", icon = "arrow-up-right" }, { "chams", "Chams (through walls)", icon = "ghost" } } })
    what:segmented({ id = "esp.box", label = "Box style", options = { { "corners", "Corners" }, { "full", "Full" } }, width = 160 })
    what:toggle({ id = "esp.fill", label = "Fill the box", bindable = false })
    what:slider({ id = "esp.boxWidth", label = "Box width", desc = "As a share of its height.", min = 30, max = 90, step = 1, suffix = "%" })
    what:segmented({ id = "esp.tracerFrom", label = "Tracers start at", options = { { "bottom", "Bottom" }, { "center", "Centre" }, { "top", "Top" }, { "mouse", "Mouse" } }, width = 232 })

    local style = page:section({ title = "Colour & weight", icon = "palette", column = 2, weight = 5 })
    style:dropdown({ id = "esp.colorMode", label = "Colour by", options = { { "custom", "One colour" }, { "team", "Team colour" }, { "health", "Health" } } })
    style:color({ id = "esp.color", label = "Colour" })
    style:color({ id = "esp.friendColor", label = "Friends" })
    style:toggle({ id = "esp.seenTint", label = "Own colour when in view", desc = "Anyone you have a clear line to. One ray per player, ten times a second.", bindable = false,
      children = function(sub) sub:color({ id = "esp.seenColor", label = "In view" }) end })
    style:toggle({ id = "esp.markTarget", label = "Colour the aim target", desc = "Whoever aim assist is on.", bindable = false,
      children = function(sub) sub:color({ id = "esp.targetColor", label = "Target" }) end })
    style:slider({ id = "esp.thickness", label = "Line weight", min = 0.5, max = 6, step = 0.5, suffix = " px" })
    style:slider({ id = "esp.textSize", label = "Text size", min = 8, max = 32, step = 1, suffix = " px" })
    style:slider({ id = "esp.chamsFill", label = "Chams fill", desc = "0 is solid, 100 is outline only.", min = 0, max = 100, step = 5, suffix = "%" })
    style:toggle({ id = "esp.chamsOutline", label = "Chams outline", bindable = false })

    local who = page:section({ title = "Who and how far", icon = "filter", column = 1, weight = 4 })
    who:toggle({ id = "esp.teamCheck", label = "Hide teammates", bindable = false })
    who:toggle({ id = "esp.displayNames", label = "Show display names", bindable = false })
    who:slider({ id = "esp.range", label = "Range", desc = "All the way right is no limit.", min = 50, max = Esp.FAR, step = 50, curve = 3.2, valueWidth = 84, format = reach(Esp.FAR) })
