-- ---------------------------------------------------------------- Movement
local function studs(v) return util.comma(v) .. " st/s" end
-- A live read-out of the flight: what it is doing, how fast, and how far that is from the boom.
-- The rail is logarithmic: the range it has to show runs from walking pace to a quarter of a
-- million studs a second, and on a straight rail everything below Mach 10 would be one pixel.
local function flightGauge(frame)
  local Flight = B.Flight
  local box = UI.frame(frame, { Name = "Gauge", Size = UDim2.new(1, -24, 1, -8), Position = UDim2.fromOffset(12, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill1A" } })
  UI.corner(box, "rControl")
  UI.text(box, "FLIGHT", "eyebrow", "faint", { Position = UDim2.fromOffset(14, 13), TextSize = 9 })
  local state = UI.text(box, "Off", "label", "ink", { Name = "State", Position = UDim2.fromOffset(14, 30) })
  local speed = UI.text(box, "0", "monoBold", "ink", { Name = "Speed", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -52, 0, 21), TextSize = 21,
    TextXAlignment = Enum.TextXAlignment.Right })
  UI.text(box, "st/s", "mono", "faint", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 28), TextSize = 11 })
  local rail = UI.frame(box, { Name = "Rail", Size = UDim2.new(1, -28, 0, 4), Position = UDim2.new(0, 14, 1, -17), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(rail, true)
  local fill = UI.frame(rail, { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundTransparency = 0, Theme = { BackgroundColor3 = "accent" } })
  UI.corner(fill, true)
  -- where the sound barrier sits on the rail
  local mark = UI.frame(rail, { Name = "Sonic", Size = UDim2.fromOffset(2, 12), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.7, 0.5),
    BackgroundTransparency = 0.35, Theme = { BackgroundColor3 = "ink" } })
  local shown, wasSonic = -1, nil
  Motion.every(function()
    if not box.Parent or not onPage("movement") then return end
    local label, value = Flight.status()
    if state.Text ~= label then state.Text = label end
    local rounded = math.floor(value + 0.5)
    if rounded ~= shown then
      shown = rounded
      speed.Text = util.comma(rounded)
    end
    local top = math.max(Config.get("fly.top"), Config.get("move.flySpeed"), 20)
    local sonic = Config.get("fly.sonic")
    local span = math.log(top / 10)
    local function along(v) return math.clamp(math.log(math.max(v, 10) / 10) / span, 0, 1) end
    fill.Size = UDim2.fromScale(along(value), 1)
    mark.Position = UDim2.fromScale(along(sonic), 0.5)
    mark.Visible = sonic <= top
    local isSonic = value >= sonic
    if isSonic ~= wasSonic then
      wasSonic = isSonic
      Theme.bind(speed, "TextColor3", isSonic and "accent" or "ink")
    end
  end, 20, "flight.gauge")
end
-- One button per Mach tier: each fires that tier's boom where the body stands.
local function boomPreview(frame)
  local Flight = B.Flight
  UI.text(frame, "Preview a boom", "label", "ink", { Position = UDim2.fromOffset(14, 10) })
  UI.text(frame, "Fires it where you stand, at Mach 1 to 32. Each doubling is a bigger one.", "caption", "sub", { Position = UDim2.fromOffset(14, 30), TextWrapped = true,
    Size = UDim2.new(1, -28, 0, 28), AutomaticSize = Enum.AutomaticSize.None, TextYAlignment = Enum.TextYAlignment.Top, LineHeight = 1.15 })
  local row = UI.frame(frame, { Name = "Tiers", Size = UDim2.new(1, -28, 0, 28), Position = UDim2.new(0, 14, 1, -38) })
  UI.list(row, "x", 6, { v = "Center" })
  for tier = 1, 6 do
    local button = Controls.pillButton(row, "M" .. 2 ^ (tier - 1), nil, function()
      if not Flight.Fx.preview(tier) then Window.toast({ title = "No character yet", text = "The preview needs a body to stand on.", icon = "info" }) end
    end, { LayoutOrder = tier, Name = "Tier" .. tier })
    button.Size = UDim2.fromOffset(0, 26)
  end
end

