-- ---------------------------------------------------------------- Players
local Players = {}
B.PlayersTab = Players
local spectating
local function stopSpectate(quiet)
  if not spectating then return end
  spectating = nil
  local camera = workspace.CurrentCamera
  local humanoid = B.humanoid()
  if camera and humanoid then camera.CameraSubject = humanoid end
  if not quiet then Window.toast({ title = "Back to you", icon = "eye-off" }) end
end
local function spectate(entry)
  if spectating == entry then stopSpectate(); return end
  if not entry.humanoid then Window.toast({ title = entry.display .. " has no character right now", icon = "triangle-alert", tone = "warn" }); return end
  spectating = entry
  workspace.CurrentCamera.CameraSubject = entry.humanoid
  Window.toast({ title = "Watching " .. entry.display, text = "Press the eye again to stop.", icon = "eye" })
end
-- the next player with a character, in name order, after the one being watched
local function watchNext()
  local entries = table.clone(Roster.list)
  table.sort(entries, function(a, b) return string.lower(a.display) < string.lower(b.display) end)
  local from = spectating and table.find(entries, spectating) or 0
  for step = 1, #entries do
    local entry = entries[(from + step - 1) % #entries + 1]
    if entry.humanoid and entry ~= spectating then
      spectating = nil
      spectate(entry)
      return
    end
  end
  Window.toast({ title = "No one else to watch", icon = "eye-off" })
end
Players.spectate, Players.stop, Players.next = spectate, stopSpectate, watchNext
function Players.watching() return spectating end
-- where a teleport to someone puts you: behind them, in front or overhead, at the gap that is set
local function landing(entry)
  local root = entry.root
  local gap, side = Config.get("players.tpGap"), Config.get("players.tpSide")
  if side == "above" then return root.Position + Vector3.new(0, gap, 0) end
  return root.Position + root.CFrame.LookVector * (side == "front" and gap or -gap) + Vector3.new(0, 1, 0)
end
Players.landing = landing
local SORTS = {
  name = function(a, b) return string.lower(a.display) < string.lower(b.display) end,
  distance = function(a, b) return (a.away or math.huge) < (b.away or math.huge) end,
  team = function(a, b)
    local ta, tb = Roster.teamName(a) or "~", Roster.teamName(b) or "~"
    if ta ~= tb then return ta < tb end
    return string.lower(a.display) < string.lower(b.display)
  end,
  health = function(a, b) return (a.alive and a.health or -1) > (b.alive and b.health or -1) end,
}

B.pages[#B.pages + 1] = function()
  Roster.start()
  Config.define("players.sort", "name")
  Config.define("players.compact", false)
  Config.define("players.announce", false)
  Config.define("players.tpSide", "behind")
  Config.define("players.tpGap", 4)
  B.own(function() stopSpectate(true) end)
  Roster.changed:connect(function(entry)
    if spectating == entry then
      if entry.gone then stopSpectate()
      elseif entry.humanoid then workspace.CurrentCamera.CameraSubject = entry.humanoid end
    end
  end)
  -- who comes and goes, if asked for
  B.connect(S.Players.PlayerAdded, function(player)
    if Config.get("players.announce") and player ~= B.LP then Window.toast({ title = player.DisplayName .. " joined", text = "@" .. player.Name, icon = "user-check" }) end
  end, "players.joined")
  B.connect(S.Players.PlayerRemoving, function(player)
    if Config.get("players.announce") and player ~= B.LP then Window.toast({ title = player.DisplayName .. " left", text = "@" .. player.Name, icon = "user-x" }) end
  end, "players.left")

  Window.page({ id = "players", title = "Players", icon = "users", group = GROUP, order = 240, build = function(page)
    page:custom(nil, function(frame)
      local card = UI.surface(frame, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.stroke(card, "ink", "strokeA")
      local stack = UI.frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(stack, "y", 0)
      local top = UI.frame(stack, { Size = UDim2.new(1, 0, 0, 52), LayoutOrder = 0 })
      local count = UI.text(top, "", "heading", "ink", { Position = UDim2.new(0, 16, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      local field, box = Controls.field(top, { Width = 210, PlaceholderText = "Filter by name" })
      field.AnchorPoint, field.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
      -- how the list is ordered
      local order = UI.frame(stack, { Name = "Order", Size = UDim2.new(1, 0, 0, 40), LayoutOrder = 1 })
      UI.text(order, "Sort by", "label", "sub", { Position = UDim2.new(0, 16, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
      local sortHolder = UI.frame(order, { Name = "Sort", Size = UDim2.fromOffset(300, 30), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0) })
      local list = UI.frame(stack, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2 })
      UI.list(list, "y", 0)
      UI.pad(list, 0, 0, 6, 0)
      local rows = {}
      local shownOrder = ""
      local function iconButton(parent, icon, x, tip, run)
        local button = UI.frame(parent, { Name = "Action_" .. icon, Size = UDim2.fromOffset(30, 30), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, x, 0.5, 0), ZIndex = 6,
          Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 1 })
        UI.corner(button, "rSmall")
        local glyph = UI.icon(button, icon, 16, "sub", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
        local hit = UI.button(button, {
          hover = function(on) Motion.to(button, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
          click = function() UI.sfx("click", 0.6); run(button) end,
        })
        UI.tooltip(hit, tip)
        return glyph, button
      end
      local function ordered()
        local entries = table.clone(Roster.list)
        local mine = B.root()
        for _, entry in ipairs(entries) do
          entry.away = (mine and entry.root) and (entry.root.Position - mine.Position).Magnitude or nil
        end
        table.sort(entries, SORTS[Config.get("players.sort")] or SORTS.name)
        return entries
      end
      local function signature(entries)
        local ids = {}
        for index, entry in ipairs(entries) do ids[index] = entry.userId end
        return table.concat(ids, ",")
      end
      local function rebuild()
        for _, row in ipairs(rows) do row.frame:Destroy() end
        table.clear(rows)
        local filter = string.lower(box.Text)
        local compact = Config.get("players.compact")
        local height, face = compact and 40 or 54, compact and 26 or 34
        local shown = 0
        local entries = ordered()
        shownOrder = signature(entries)
        for index, entry in ipairs(entries) do
          if filter == "" or string.find(string.lower(entry.display), filter, 1, true) or string.find(string.lower(entry.name), filter, 1, true) then
            shown += 1
            local row = UI.frame(list, { Name = entry.name, Size = UDim2.new(1, 0, 0, height), LayoutOrder = index })
            UI.frame(row, { Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
            local avatar = UI.new("ImageLabel", { Size = UDim2.fromOffset(face, face), Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0.9,
              Theme = { BackgroundColor3 = "ink" }, Image = "rbxthumb://type=AvatarHeadShot&id=" .. entry.userId .. "&w=150&h=150", Parent = row })
            UI.corner(avatar, true)
            local left = face + 26
            local title = UI.text(row, entry.display, "label", "ink", { Position = compact and UDim2.new(0, left, 0.5, 0) or UDim2.fromOffset(left, 10),
              AnchorPoint = compact and Vector2.new(0, 0.5) or Vector2.new(0, 0), Size = compact and UDim2.new(0.34, 0, 0, 18) or UDim2.new(1, -330, 0, 18),
              AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd })
            local sub = UI.text(row, "@" .. entry.name, "caption", "faint", { Position = compact and UDim2.new(0.34, left + 8, 0.5, 0) or UDim2.fromOffset(left, 29),
              AnchorPoint = compact and Vector2.new(0, 0.5) or Vector2.new(0, 0), Size = compact and UDim2.new(0.66, -(left + 300), 0, 16) or UDim2.new(1, -330, 0, 16),
              AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 11.5 })
            -- health, as a bar and a figure
            local health = UI.frame(row, { Name = "Health", Size = UDim2.fromOffset(46, 4), AnchorPoint = Vector2.new(1, 0.5),
              Position = compact and UDim2.new(1, -236, 0.5, 0) or UDim2.new(1, -160, 0.5, 10),
              Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
            UI.corner(health, true)
            local healthFill = UI.frame(health, { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundTransparency = 0 })
            UI.corner(healthFill, true)
            local distance = UI.text(row, "", "mono", "sub", { Name = "Distance", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -160, 0.5, compact and 0 or -7) })
            local eye = iconButton(row, "eye", -118, "Watch", function() spectate(entry) end)
            iconButton(row, "navigation", -84, "Teleport to", function()
              if entry.root then Move.start(); Move.teleport(landing(entry))
              else Window.toast({ title = entry.display .. " has no character right now", icon = "triangle-alert", tone = "warn" }) end
            end)
            local star
            star = iconButton(row, "star", -50, "Friend: skipped by aim, own colour in ESP", function()
              Roster.setFriend(entry, not Roster.isFriend(entry))
            end)
            -- the rest: marks, and what to copy
            iconButton(row, "ellipsis", -16, "More", function(anchor)
              local target, hidden = Roster.isTarget(entry), Roster.isHidden(entry)
              UI.menu(anchor, {
                { label = target and "Remove the target mark" or "Mark as a target", icon = "crosshair", checked = target, run = function() Roster.setTarget(entry, not target) end },
                { label = hidden and "Show in ESP and aim again" or "Hide from ESP and aim", icon = "eye-off", checked = hidden, run = function() Roster.setHidden(entry, not hidden) end },
                "divider",
                { label = "Copy username", icon = "at-sign", run = function()
                  Window.toast(B.clipboard(entry.name) and { title = "Copied @" .. entry.name, icon = "clipboard", tone = "ok" } or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
                end },
                { label = "Copy user ID", icon = "hash", hint = tostring(entry.userId), run = function()
                  Window.toast(B.clipboard(tostring(entry.userId)) and { title = "Copied " .. entry.userId, icon = "clipboard", tone = "ok" } or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
                end },
              }, { align = "right", width = 232 })
            end)
            rows[#rows + 1] = { frame = row, entry = entry, distance = distance, sub = sub, eye = eye, star = star, title = title, health = healthFill }
          end
        end
        count.Text = (#Roster.list == 0 and "No one else is here") or (shown .. (shown == 1 and " player" or " players"))
      end
      local pending = false
      local function soon()
        if pending then return end
        pending = true
        task.delay(0.15, function() pending = false; if list.Parent then rebuild() end end)
      end
      Controls.segmentedBar(sortHolder, { { "name", "Name" }, { "distance", "Nearest" }, { "team", "Team" }, { "health", "Health" } }, Config.get("players.sort"), function(value)
        Config.set("players.sort", value)
      end)
      Config.on("players.sort", soon)
      Config.on("players.compact", soon)
      Roster.changed:connect(function() soon() end)
      box:GetPropertyChangedSignal("Text"):Connect(soon)
      rebuild()
      Motion.every(function()
        if not list.Parent or not onPage("players") then return end
        local mine = B.root()
        for _, row in ipairs(rows) do
          local entry = row.entry
          local team = entry.player.Team
          local where = (mine and entry.root) and (util.studs((entry.root.Position - mine.Position).Magnitude) .. " st") or "—"
          row.distance.Text = where
          local marks = (Roster.isTarget(entry) and "  ·  target" or "") .. (Roster.isHidden(entry) and "  ·  hidden" or "")
          row.sub.Text = "@" .. entry.name .. (team and ("  ·  " .. team.Name) or "") .. (entry.alive and "" or "  ·  down") .. marks
          local share = entry.alive and util.clamp01((entry.health or 0) / (entry.maxHealth or 100)) or 0
          row.health.Size = UDim2.fromScale(share, 1)
          row.health.BackgroundColor3 = Color3.fromHSV(0.33 * share, 0.78, 0.96)
          Theme.bind(row.eye, "ImageColor3", spectating == entry and "accent" or "sub")
          Theme.bind(row.star, "ImageColor3", Roster.isFriend(entry) and "ok" or "sub")
          Theme.bind(row.title, "TextColor3", Roster.isTarget(entry) and "bad" or (Roster.isHidden(entry) and "faint" or "ink"))
        end
        -- an order that depends on where people are goes stale: put it right when it has changed
        local sort = Config.get("players.sort")
        if (sort == "distance" or sort == "health") and not pending and signature(ordered()) ~= shownOrder then soon() end
      end, 3, "players.rows")
    end)

    local tp = page:section({ title = "Teleporting to someone", icon = "navigation", column = 1 })
    tp:segmented({ id = "players.tpSide", label = "Land", options = { { "behind", "Behind" }, { "front", "In front" }, { "above", "Above" } }, width = 232 })
    tp:slider({ id = "players.tpGap", label = "This far from them", min = 1, max = 200, step = 1, curve = 2, suffix = " st" })

    local watch = page:section({ title = "Watching", icon = "eye", column = 2 })
    watch:button({ id = "players.watchNext", label = "Watch the next player", desc = "Bind it to a key to flick through the server.", text = "Next", run = watchNext })
    watch:button({ id = "players.watchStop", label = "Back to yourself", text = "Stop", run = function() stopSpectate() end })

    local listing = page:section({ title = "The list", icon = "list", column = 1 })
    listing:toggle({ id = "players.compact", label = "Compact rows", bindable = false })
    listing:toggle({ id = "players.announce", label = "Say who joins and leaves", bindable = false })

    local marks = page:section({ title = "Marks", icon = "bookmark", column = 2, desc = "Kept by account, so they are still there in the next server." })
    marks:button({ label = "Forget every friend", text = "Clear", bindable = false, run = function() Roster.clear("friends"); Window.toast({ title = "No friends marked", icon = "star" }) end })
    marks:button({ label = "Forget every target", text = "Clear", bindable = false, run = function() Roster.clear("targets"); Window.toast({ title = "No targets marked", icon = "crosshair" }) end })
    marks:button({ label = "Show everyone again", text = "Clear", bindable = false, run = function() Roster.clear("hidden"); Window.toast({ title = "No one is hidden", icon = "eye" }) end })
  end })
end

-- ---------------------------------------------------------------- World
B.pages[#B.pages + 1] = function()
  World.start()
  Window.page({ id = "world", title = "Server", icon = "server", group = GROUP, order = 250, build = function(page)
    local session = page:section({ title = "Session", icon = "shield", column = 1 })
    session:toggle({ id = "world.antiAfk", label = "Anti-AFK", desc = "Stops the 20-minute idle kick.", bindable = false })
    session:toggle({ id = "world.autoExec", label = "Follow me through teleports", desc = "Runs BASED again when the game sends you to another place.", bindable = false })
    if type(setfpscap) == "function" then
      session:dropdown({ id = "world.fpsCap", label = "FPS limit", options = { { 0, "Unlimited" }, { 30, "30" }, { 60, "60" }, { 75, "75" }, { 90, "90" }, { 120, "120" }, { 144, "144" },
        { 165, "165" }, { 240, "240" }, { 360, "360" }, { 480, "480" } } })
    end

    local server = page:section({ title = "This server", icon = "server", column = 2 })
    server:button({ id = "server.rejoin", label = "Rejoin", desc = "Leave and come straight back.", text = "Rejoin", run = Server.rejoin })
    server:dropdown({ id = "world.hopMode", label = "Hop to", options = { { "random", "Any other server" }, { "empty", "The emptiest" }, { "full", "The fullest with room" } } })
    server:button({ id = "server.hop", label = "Server hop", desc = "Join a different server of this game.", text = "Hop", run = Server.hop })
    server:button({ label = "Copy join script", desc = "A line that lands in this exact server.", text = "Copy", run = Server.copyJoin, bindable = false })
    server:button({ label = "Copy server ID", text = "Copy", bindable = false, run = function()
      Window.toast(B.clipboard(game.JobId) and { title = "Server ID copied", icon = "clipboard", tone = "ok" } or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
    end })
    local function stat(label, read)
      server:custom({ height = 34, build = function(frame)
        UI.text(frame, label, "label", "sub", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
        local value = UI.text(frame, "", "mono", "ink", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
        Motion.every(function()
          if value.Parent and onPage("world") then value.Text = read() end
        end, 1, "world.stat")
      end })
    end
    stat("Players", function() return #S.Players:GetPlayers() .. " / " .. S.Players.MaxPlayers .. "   ·   " .. math.floor(Hud.ping() + 0.5) .. " ms" end)
    stat("Up for", function()
      local s = math.floor(workspace.DistributedGameTime)
      return string.format("%d:%02d:%02d", s // 3600, s // 60 % 60, s % 60)
    end)
  end })
end
end
do -- 50_settings.lua
-- ============================================================================
--  50 settings   the hub's own preferences and the Settings tab
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local Assets = B.Assets
local Prefs = {}
B.Prefs = Prefs
B.pages = B.pages or {}

function Prefs.define()
  Config.define("app.scheme", "dark")
  Config.define("app.accent", Theme.accents[1].color)
  Config.define("app.glass", 60)
  Config.define("app.blur", true)
  Config.define("app.radius", 100)
  Config.define("app.scale", 100)
  Config.define("app.motion", "full")
  Config.define("app.motionSpeed", 100)
  Config.define("app.sfx", true)
  Config.define("app.sfxVolume", 45)
  Config.define("app.key.menu", "RightControl")
  Config.define("app.key.panic", "None")
  Config.define("app.freeCursor", true)
  Config.define("app.window.x", 0.5)
  Config.define("app.window.y", 0.5)
  Config.define("app.intro", "cinematic")
  Config.define("app.introVolume", 50)
  Config.define("app.filmQuality", "auto")
  Config.define("app.island", true)
  Config.define("app.keyHud", true)
  Config.define("app.toasts", true)
end

function Prefs.apply()
  Theme.state.scheme = Config.get("app.scheme")
  Theme.state.accent = Config.get("app.accent")
  Theme.state.glass = Config.get("app.glass") / 100
  Theme.state.radius = Config.get("app.radius") / 100
  Theme.apply()
  Motion.reduced = Config.get("app.motion") == "reduced"
  Motion.speed = Config.get("app.motionSpeed") / 100
  UI.sfxOn = Config.get("app.sfx")
  UI.sfxVolume = Config.get("app.sfxVolume") / 100
  B.Blur.set(Config.get("app.blur") == true)

  Config.on("app.scheme", function(v) Theme.set({ scheme = v }) end)
  Config.on("app.accent", function(v) Theme.set({ accent = v }) end)
  Config.on("app.glass", function(v) Theme.set({ glass = v / 100 }) end)
  Config.on("app.radius", function(v) Theme.set({ radius = v / 100 }) end)
  Config.on("app.blur", function(v) B.Blur.set(v == true) end)
  Config.on("app.scale", function() Window.rescale() end)
  Config.on("app.motion", function(v) Motion.reduced = v == "reduced" end)
  Config.on("app.motionSpeed", function(v) Motion.speed = v / 100 end)
  Config.on("app.sfx", function(v) UI.sfxOn = v end)
  Config.on("app.sfxVolume", function(v) UI.sfxVolume = v / 100 end)
  Config.on("app.freeCursor", function(v) if Window.modal then Window.modal.Visible = Window.open and v end end)
end

-- the accent row: a swatch per preset, then a free colour
local function accentPicker(frame)
  local row = UI.frame(frame, { Size = UDim2.new(1, -28, 0, 30), Position = UDim2.fromOffset(14, 8) })
  UI.list(row, "x", 9, { v = "Center" })
  local rings = {}
  local function mark()
    local current = Config.get("app.accent")
    for color, ring in pairs(rings) do
      Motion.to(ring, "Transparency", util.toHex(color) == util.toHex(current) and 0 or 1, "quick")
    end
  end
  for index, accent in ipairs(Theme.accents) do
    local swatch = UI.frame(row, { Size = UDim2.fromOffset(24, 24), BackgroundTransparency = 0, BackgroundColor3 = accent.color, LayoutOrder = index })
    UI.corner(swatch, true)
    local ring = Instance.new("UIStroke")
    ring.Thickness = 2
    ring.Transparency = 1
    pcall(function() ring.BorderStrokePosition = Enum.BorderStrokePosition.Outer end)
    pcall(function() ring.BorderOffset = UDim.new(0, 2) end)
    Theme.bind(ring, "Color", "ink")
    ring.Parent = swatch
    rings[accent.color] = ring
    local scale = UI.scaleOf(swatch)
    local hit = UI.button(swatch, {
      hover = function(on) Motion.to(scale, "Scale", on and 1.12 or 1, "snappy") end,
      click = function() UI.sfx("click", 0.6); Config.set("app.accent", accent.color) end,
    })
    UI.tooltip(hit, accent.label)
  end
  local custom = UI.frame(row, { Size = UDim2.fromOffset(24, 24), LayoutOrder = 99, Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(custom, true)
  UI.icon(custom, "pipette", 13, "sub", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
  local hit = UI.button(custom, { click = function()
    Controls.colorPopover(custom, Config.get("app.accent"), function(color) Config.set("app.accent", color) end)
  end })
  UI.tooltip(hit, "Any colour")
  Config.on("app.accent", function() if row.Parent then mark() end end)
  mark()
end

B.pages[#B.pages + 1] = function()
  Window.page({ id = "settings", title = "Settings", icon = "settings", group = "Hub", order = 900, eyebrow = "Make it yours", build = function(page)
    local look = page:section({ title = "Appearance", icon = "palette", desc = "Changes apply live." })
    look:segmented({ id = "app.scheme", label = "Scheme", options = { { "dark", "Graphite" }, { "midnight", "Midnight" }, { "light", "Porcelain" } }, width = 232 })
    look:custom({ height = 46, name = "Accent", build = accentPicker })
    look:slider({ id = "app.glass", label = "Glass", desc = "Clear on the left, tinted on the right.", min = 0, max = 100, step = 1, suffix = "%" })
    look:toggle({ id = "app.blur", label = "Real blur", desc = "Blurs the game behind the window. Needs graphics quality 8 or higher.", bindable = false })
    look:slider({ id = "app.radius", label = "Corner roundness", min = 40, max = 130, step = 5, suffix = "%" })
    look:slider({ id = "app.scale", label = "Interface size", desc = "It never grows past the screen.", min = 60, max = 160, step = 5, suffix = "%" })

    local motion = page:section({ title = "Motion & sound", icon = "activity" })
    motion:segmented({ id = "app.motion", label = "Animations", options = { { "full", "Full" }, { "reduced", "Reduced" } }, width = 170 })
    motion:slider({ id = "app.motionSpeed", label = "Animation speed", min = 40, max = 250, step = 10, suffix = "%" })
    motion:toggle({ id = "app.sfx", label = "Interface sounds", bindable = false })
    motion:slider({ id = "app.sfxVolume", label = "Sound volume", min = 0, max = 100, step = 5, suffix = "%" })

    local keys = page:section({ title = "Keys", icon = "keyboard" })
    keys:keybind({ id = "app.key.menu", label = "Open / close the hub" })
    keys:keybind({ id = "app.key.panic", label = "Panic", desc = "Unloads BASED instantly: every feature off, nothing left behind." })
    keys:toggle({ id = "app.freeCursor", label = "Free the cursor while open", desc = "Unlocks the mouse in first-person games.", bindable = false })
    keys:button({ label = "Every key, on a keyboard", desc = "What each one does, and a click to change it.", text = "Open", bindable = false, run = function() Window.go("keys") end })
    keys:note({ icon = "info", text = "Right-click any toggle or button to bind it to a key." })

    local screen = page:section({ title = "On screen", icon = "monitor", desc = "What stays up while the hub is hidden." })
    screen:toggle({ id = "app.island", label = "The island", desc = "The pill at the top: frame rate and ping, and your speed in flight. Click it to bring the hub back.", bindable = false })
    screen:toggle({ id = "app.keyHud", label = "My keys", desc = "Each bound feature with its key, lit while it is on.", bindable = false })
    screen:toggle({ id = "app.toasts", label = "Say which game this is on launch", bindable = false })

    if B.Board and B.Board.installed() then
      B.Board.define()
      local board = page:section({ title = "Home board", icon = "film", desc = "The film on the Home tab." })
      board:toggle({ id = "home.board", label = "Play it", desc = "Silent in the card. Off shows a still instead.", bindable = false })
      board:toggle({ id = "home.boardHover", label = "Open on hover", desc = "Rest the mouse on it: it comes forward and the sound comes in.", bindable = false })
      board:slider({ id = "home.boardVolume", label = "Sound volume", min = 0, max = 100, step = 5, suffix = "%" })
      board:slider({ id = "home.boardSize", label = "Opened size", desc = "How much of the screen's width it takes.", min = 30, max = 90, step = 2, suffix = "%" })
      board:dropdown({ id = "home.boardQuality", label = "Picture", options = { { "ultra", "Ultra · 1820×1024" }, { "hd", "HD · 1024×576" } } })
    end

    local intro = page:section({ title = "Intro", icon = "clapperboard" })
    intro:segmented({ id = "app.intro", label = "On launch", options = { { "cinematic", "Cinematic" }, { "quick", "Quick" }, { "off", "Off" } }, width = 232 })
    -- the film and its music are settings only where there is a film: without one the intro is the name alone
    if B.Film and not B.Assets.lite and B.Film.pick(Config.get("app.filmQuality")) then
      intro:slider({ id = "app.introVolume", label = "Music volume", min = 0, max = 100, step = 5, suffix = "%" })
      -- a choice of picture only where there is one to make: an install fetches the one size its screen suits
      if B.Film.has("hd") and B.Film.has("ultra") then
        intro:dropdown({ id = "app.filmQuality", label = "Film quality", options = { { "auto", "Auto" }, { "ultra", "Ultra · 1820×1024" }, { "hd", "HD · 1024×576" } } })
      end
    end
    intro:button({ label = "Replay the intro", text = "Play", run = function()
      if B.Loader then Window.show(false); B.Loader.run(function() Window.show(true) end, "cinematic") end
    end })

    local data = page:section({ title = "Configs", icon = "save", desc = "Feature settings save on their own." })
    data:segmented({ label = "Saved", options = { { "global", "One for all games" }, { "game", "One per game" } }, default = Config.profileMode, width = 232,
      changed = function(mode) if mode ~= Config.profileMode then Config.setMode(mode); Window.toast({ title = "Config scope changed", text = mode == "game" and "This game now has its own settings." or "One config for every game.", icon = "save" }) end end })
    data:button({ label = "Copy settings", desc = "Share a setup as text.", text = "Copy", run = function()
      local json = Config.export()
      if json and B.clipboard(json) then Window.toast({ title = "Copied", text = "Settings are on the clipboard.", icon = "clipboard", tone = "ok" })
      else Window.toast({ title = "Could not copy", text = "This executor has no clipboard access.", icon = "triangle-alert", tone = "warn" }) end
    end })
    local importBox
    importBox = data:input({ label = "Paste settings", placeholder = "Paste, then Enter", width = 170, changed = function(text)
      if text == "" then return end
      local ok, count = Config.import(text)
      importBox.box.Text = ""
      Window.toast(ok and { title = "Imported", text = count .. " settings applied.", icon = "circle-check", tone = "ok" }
        or { title = "Not a BASED config", text = "That text could not be read.", icon = "triangle-alert", tone = "warn" })
    end })
    data:button({ label = "Reset every feature", desc = "Appearance and keys are kept.", text = "Reset", style = "danger", run = function()
      Config.resetAll(false)
      Window.toast({ title = "Features reset", text = "Everything is back to its default.", icon = "rotate-ccw" })
    end })

    local about = page:section({ title = "About", icon = "info" })
    local function stat(label, value)
      about:custom({ height = 34, build = function(frame)
        UI.text(frame, label, "label", "sub", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
        local text = UI.text(frame, "", "mono", "ink", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
        if type(value) == "function" then
          text.Text = tostring(value())
          Motion.every(function() if text.Parent and Window.open and Window.current and Window.current.id == "settings" then text.Text = tostring(value()) end end, 2, "about")
        else text.Text = tostring(value) end
      end })
    end
    stat("Version", B.VERSION .. "  ·  " .. B.BUILD)
    stat("Executor", B.executor)
    stat("Assets", function() return Assets.lite and "missing (lite mode)" or (Assets.calls .. " registered this session") end)
    stat("Started in", function() return (B.bootMs or 0) .. " ms" end)
    stat("Faults", function() return #B.faults end)
    about:button({ label = "Copy diagnostics", text = "Copy", run = function()
      local lines = { "BASED " .. B.VERSION .. " " .. B.BUILD, "executor " .. B.executor, "place " .. game.PlaceId .. " universe " .. game.GameId }
      for _, fault in ipairs(B.faults) do lines[#lines + 1] = string.format("[%.1fs] %s: %s", fault.at, fault.scope, fault.message) end
      B.clipboard(table.concat(lines, "\n"))
      Window.toast({ title = "Diagnostics copied", icon = "clipboard", tone = "ok" })
    end })
    about:button({ label = "Unload BASED", text = "Unload", style = "danger", bindable = false, run = function() B.unload() end })
    about:note({ text = "Fonts: Inter, Instrument Serif, Archivo, Geist Mono (SIL OFL). Icons: Lucide (ISC). Interface sounds: Kenney (CC0)." })
  end })
end
end
do -- 51_keys.lua
-- ============================================================================
--  51 keys     the keyboard, drawn, with what every key does written on it
--
--  A key can be given a feature from either side: right-click a toggle or a
--  button and press a key, or come here, click the key and pick the feature.
--  The picture is the same either way. A bound key carries its feature's name
--  and lights up while that feature is on; the keys the hub and flight already
--  use are marked; a key asked to do two things is flagged. The same list can
--  sit on screen while the hub is hidden.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local UIS = S.UserInputService
local Keys = { caps = {}, builtin = {} }
B.Keys = Keys
B.pages = B.pages or {}

-- An ANSI board in units of one key; every row is fifteen units wide. A unit of 48 keeps every
-- key an even number of pixels wide, which matters: a UDim offset is a whole number, and a key
-- anchored at its centre with an odd width sits half a pixel off its neighbours.
local UNIT, GAP, HEIGHT = 44, 4, 40
local function k(key, width) return { key = key, width = width or 1 } end
local function gap(width) return { width = width } end
local ROWS = {
  { k("Escape"), gap(1), k("F1"), k("F2"), k("F3"), k("F4"), gap(0.5), k("F5"), k("F6"), k("F7"), k("F8"), gap(0.5), k("F9"), k("F10"), k("F11"), k("F12") },
  { k("Backquote"), k("One"), k("Two"), k("Three"), k("Four"), k("Five"), k("Six"), k("Seven"), k("Eight"), k("Nine"), k("Zero"), k("Minus"), k("Equals"), k("Backspace", 2) },
  { k("Tab", 1.5), k("Q"), k("W"), k("E"), k("R"), k("T"), k("Y"), k("U"), k("I"), k("O"), k("P"), k("LeftBracket"), k("RightBracket"), k("BackSlash", 1.5) },
  { k("CapsLock", 1.75), k("A"), k("S"), k("D"), k("F"), k("G"), k("H"), k("J"), k("K"), k("L"), k("Semicolon"), k("Quote"), k("Return", 2.25) },
  { k("LeftShift", 2.25), k("Z"), k("X"), k("C"), k("V"), k("B"), k("N"), k("M"), k("Comma"), k("Period"), k("Slash"), k("RightShift", 2.75) },
  { k("LeftControl", 1.5), k("LeftAlt", 1.25), k("Space", 5.5), k("RightAlt", 1.25), k("RightControl", 1.5), k("Left"), k("Up"), k("Down"), k("Right") },
  { k("Insert", 1.25), k("Delete", 1.25), k("Home", 1.25), k("End", 1.25), k("PageUp", 1.25), k("PageDown", 1.25), gap(0.5), k("MouseButton2", 2.25), k("MouseButton3", 2.25) },
}
Keys.width = 15 * (UNIT + GAP) - GAP
Keys.height = #ROWS * (HEIGHT + GAP) - GAP
local LONG = { MouseButton2 = "Right click", MouseButton3 = "Middle click", Backspace = "Backspace", Return = "Enter", CapsLock = "Caps", Space = "Space",
  LeftShift = "Shift", RightShift = "Shift", LeftControl = "Ctrl", RightControl = "Ctrl", LeftAlt = "Alt", RightAlt = "Alt", Tab = "Tab", Escape = "Esc",
  Insert = "Ins", Delete = "Del", PageUp = "PgUp", PageDown = "PgDn" }
-- on the cap the two Shifts and the two Ctrls are told apart by where they sit; in a sentence they need saying
local function capLabel(key) return LONG[key] or Config.keyLabel(key) end
local function keyName(key) return Config.keyLabel(key) end

-- ---------------------------------------------------------------- what is on a key
-- the keys the hub and flight already use, read fresh: three of them can be moved
local function readBuiltins()
  local map = {}
  local function put(key, short, what, flag)
    if type(key) ~= "string" or key == "None" then return end
    map[key] = map[key] or {}
    table.insert(map[key], { short = short, what = what, flag = flag })
  end
  put(Config.get("app.key.menu"), "Menu", "opens and closes the hub", "app.key.menu")
  put(Config.get("app.key.panic"), "Panic", "unloads BASED", "app.key.panic")
  put(Config.get("fly.key.boost"), "Boost", "flight: boost", "fly.key.boost")
  put(Config.get("fly.key.down"), "Descend", "flight: come down", "fly.key.down")
  put("Space", "Climb", "flight: charge on the ground, climb in the air")
  for _, key in ipairs({ "W", "A", "S", "D" }) do put(key, "Move", "walk and steer") end
  Keys.builtin = map
  return map
end
local function featureOf(id)
  local entry = Controls.bindables[id]
  local kind = entry and entry.kind or (type(Config.get(id)) == "boolean" and "toggle" or "button")
  return entry and entry.label or id, kind, entry and entry.page and entry.page.title or nil
end
-- every feature bound to `key`, by name
function Keys.on(key)
  local list = {}
  for id, bind in pairs(Config.binds) do
    if bind.key == key then
      local label, kind, page = featureOf(id)
      list[#list + 1] = { id = id, label = label, kind = kind, page = page, mode = bind.mode, on = Config.get(id) == true }
    end
  end
  table.sort(list, function(a, b) return a.label < b.label end)
  return list
end
-- every bind there is, in keyboard order
function Keys.all()
  local order, list = {}, {}
  for _, row in ipairs(ROWS) do
    for _, item in ipairs(row) do
      if item.key then order[item.key] = #list + 1; list[#list + 1] = item.key end
    end
  end
  local out = {}
  for id, bind in pairs(Config.binds) do
    if bind.key then
      local label, kind, page = featureOf(id)
      out[#out + 1] = { id = id, key = bind.key, label = label, kind = kind, page = page, mode = bind.mode, on = Config.get(id) == true }
    end
  end
  table.sort(out, function(a, b)
    local ka, kb = order[a.key] or 999, order[b.key] or 999
    if ka ~= kb then return ka < kb end
    return a.label < b.label
  end)
  return out
end
function Keys.describe(key)
  local features, roles = Keys.on(key), Keys.builtin[key]
  local parts = {}
  for _, f in ipairs(features) do
    parts[#parts + 1] = f.label .. (f.kind == "toggle" and (f.mode == "hold" and " (while held" or " (toggle") .. (f.on and ", on)" or ", off)") or " (runs it)")
  end
  for _, role in ipairs(roles or {}) do parts[#parts + 1] = role.what end
  local name = keyName(key)
  if #parts == 0 then return name .. "  ·  free. Click it to give it a feature." end
  local clash = #features > 1 or (#features > 0 and roles ~= nil)
  return name .. "  ·  " .. table.concat(parts, "  +  ") .. (clash and "   — more than one thing on this key" or "")
end

-- ---------------------------------------------------------------- menus
local function menuRow(content, order, item, close)
  local row = UI.frame(content, { Name = item.name or "Item", Size = UDim2.new(1, 0, 0, 32), LayoutOrder = order, Theme = { BackgroundColor3 = "ink" } })
  UI.corner(row, "rSmall")
  local x = 10
  if item.icon then
    UI.icon(row, item.icon, 16, item.danger and "bad" or "sub", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
    x = 34
  end
  UI.text(row, item.label, "label", item.danger and "bad" or "ink", { Position = UDim2.new(0, x, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13,
    Size = UDim2.new(1, -(x + (item.hint and 78 or 30)), 0, 18), AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd })
  if item.checked then
    UI.icon(row, "check", 15, "accent", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
  elseif item.hint then
    UI.text(row, item.hint, "mono", "faint", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
  end
  UI.button(row, {
    hover = function(on) Motion.to(row, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
    click = function()
      UI.sfx("click", 0.6)
      close()
      if item.run then B.try("keys.menu", item.run) end
    end,
  })
  return row
end
-- pick a feature for `key`: every toggle and button the hub has, searchable
function Keys.pick(anchor, key)
  local list = {}
  for id, entry in pairs(Controls.bindables) do
    local bind = Config.bindOf(id)
    if not (bind and bind.key == key) then
      list[#list + 1] = { id = id, label = entry.label, page = entry.page and entry.page.title or "", key = bind and bind.key or nil }
    end
  end
  table.sort(list, function(a, b) return a.label < b.label end)
  return UI.popover(anchor, { width = 276, align = "center", pad = 8, gap = 6 }, function(content, close)
    UI.text(content, "Give " .. keyName(key) .. " a feature", "eyebrow", "faint", { LayoutOrder = 1, TextSize = 9 })
    local _, box = Controls.field(content, { Width = 260, PlaceholderText = "Search " .. #list .. " features" }, function() end)
    box.Parent.LayoutOrder = 2
    local holder = UI.frame(content, { Name = "List", Size = UDim2.new(1, 0, 0, 238), LayoutOrder = 3, ClipsDescendants = true })
    local scroller = UI.scroll(holder, { Size = UDim2.fromScale(1, 1), Name = "Scroll" })
    local rows = UI.frame(scroller, { Name = "Rows", Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
    UI.list(rows, "y", 2)
    local made = {}
    for index, feature in ipairs(list) do
      local row = menuRow(rows, index, { name = feature.id, label = feature.label, hint = feature.key and Config.keyLabel(feature.key) or feature.page, run = function()
        Config.bind(feature.id, key)
        Window.toast({ title = feature.label .. " is on " .. keyName(key), text = "Right-click the key to clear it.", icon = "keyboard" })
      end }, close)
      made[index] = { row = row, text = string.lower(feature.label .. " " .. feature.page) }
    end
    if #list == 0 then
      UI.text(rows, "Nothing left to bind: open the other tabs once so their switches are known.", "caption", "sub", { TextWrapped = true, Size = UDim2.new(1, -8, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y })
    end
    box:GetPropertyChangedSignal("Text"):Connect(function()
      local query = string.lower(box.Text)
      for _, item in ipairs(made) do item.row.Visible = query == "" or string.find(item.text, query, 1, true) ~= nil end
    end)
  end)
end
-- what clicking a key opens: what is on it, and what can be done about that
function Keys.menu(anchor, key)
  local features, roles = Keys.on(key), Keys.builtin[key]
  return UI.popover(anchor, { width = 252, align = "center" }, function(content, close)
    local order = 0
    local function add(item) order += 1; return menuRow(content, order, item, close) end
    local head = UI.frame(content, { Name = "Head", Size = UDim2.new(1, 0, 0, 30), LayoutOrder = 0 })
    UI.text(head, keyName(key), "heading", "ink", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
    UI.text(head, #features == 0 and (roles and roles[1].short or "Free") or (#features .. (#features == 1 and " feature" or " features")), "mono", "faint",
      { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
    for _, f in ipairs(features) do
      if f.kind == "toggle" then
        add({ name = "Hold_" .. f.id, label = f.label .. ": only while held", icon = "hand", checked = f.mode == "hold", run = function()
          Config.bind(f.id, key, f.mode == "hold" and "toggle" or "hold")
        end })
      end
      add({ name = "Unbind_" .. f.id, label = "Take " .. f.label .. " off this key", icon = "x", danger = true, run = function() Config.bind(f.id, nil) end })
    end
    for _, role in ipairs(roles or {}) do
      if role.flag then
        add({ name = "Move_" .. role.flag, label = "Move " .. string.lower(role.short) .. " to another key…", icon = "keyboard", run = function()
          Window.toast({ title = "Press a key", text = "Esc cancels · Backspace clears", icon = "keyboard", time = 2.2 })
          Controls.captureKey(function(next, cancelled)
            if not cancelled then Config.set(role.flag, next or "None") end
          end)
        end })
      end
    end
    add({ name = "Bind", label = "Bind a feature to this key…", icon = "plus", run = function() task.defer(Keys.pick, anchor, key) end })
  end)
end
function Keys.clear(key)
  local cleared = 0
  for _, f in ipairs(Keys.on(key)) do
    Config.bind(f.id, nil)
    cleared += 1
  end
  if cleared > 0 then Window.toast({ title = keyName(key) .. " is free again", text = cleared .. (cleared == 1 and " feature taken off it." or " features taken off it."), icon = "keyboard" }) end
  return cleared
end

-- ---------------------------------------------------------------- the board
local function tint(instance, property, token) Theme.bind(instance, property, token) end
local function fixed(instance, property, value)
  Theme.unbind(instance, property)
  instance[property] = value
end
local function paint(entry)
  local key = entry.key
  local features, roles = Keys.on(key), Keys.builtin[key]
  local on = false
  for _, f in ipairs(features) do on = on or f.on end
  local clash = #features > 1 or (#features > 0 and roles ~= nil)
  entry.features, entry.roles, entry.clash, entry.lit = features, roles, clash, on
  local cap, label, what, stroke = entry.cap, entry.label, entry.what, entry.stroke
  if #features > 0 then
    -- bound: the feature's name on the key, solid while it is on
    tint(cap, "BackgroundColor3", "accent")
    fixed(cap, "BackgroundTransparency", on and 0 or 0.8)
    tint(label, "TextColor3", on and "accentInk" or "ink")
    tint(what, "TextColor3", on and "accentInk" or "ink")
    what.Text = features[1].label .. (#features > 1 and ("  +" .. #features - 1) or "")
    tint(stroke, "Color", clash and "warn" or "accent")
    fixed(stroke, "Transparency", clash and 0 or 0.35)
  elseif roles then
    -- the hub's own, or flight's
    tint(cap, "BackgroundColor3", "ink")
    tint(cap, "BackgroundTransparency", "fill2A")
    tint(label, "TextColor3", "ink")
    tint(what, "TextColor3", "faint")
    what.Text = roles[1].short
    tint(stroke, "Color", "ink")
    tint(stroke, "Transparency", "stroke2A")
  else
    tint(cap, "BackgroundColor3", "ink")
    tint(cap, "BackgroundTransparency", "fill1A")
    tint(label, "TextColor3", "sub")
    what.Text = ""
    tint(stroke, "Color", "ink")
    tint(stroke, "Transparency", "strokeA")
  end
  local named = what.Text ~= ""
  what.Visible = named
  label.Position = named and UDim2.new(0.5, 0, 0, 13) or UDim2.fromScale(0.5, 0.5)
end
local repaintQueued = false
function Keys.repaint()
  if repaintQueued then return end
  repaintQueued = true
  task.defer(function()
    repaintQueued = false
    readBuiltins()
    for _, entry in pairs(Keys.caps) do
      if entry.cap.Parent then paint(entry) end
    end
    if Keys.renderList then Keys.renderList() end
    if Keys.renderHud then Keys.renderHud() end
  end)
end
local function board(frame)
  local holder = UI.frame(frame, { Name = "Board", Size = UDim2.fromOffset(Keys.width, Keys.height), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 6) })
  local legend = UI.text(frame, "", "caption", "sub", { Name = "Legend", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, Keys.height + 18), Size = UDim2.fromOffset(Keys.width, 16),
    AutomaticSize = Enum.AutomaticSize.None, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd })
  local RESTING = "Click a key to give it a feature.  Right-click a key to clear it.  Bound keys light up while their feature is on."
  legend.Text = RESTING
  Keys.legend = legend
  readBuiltins()
  for rowIndex, row in ipairs(ROWS) do
    local x = 0
    local y = (rowIndex - 1) * (HEIGHT + GAP)
    for _, item in ipairs(row) do
      local width = item.width * (UNIT + GAP) - GAP
      if item.key then
        local key = item.key
        -- anchored at its centre, so the press shrinks it in place
        local cap = UI.pressable(holder, { Name = "Cap_" .. key, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(x + width / 2, y + HEIGHT / 2),
          Size = UDim2.fromOffset(width, HEIGHT) })
        UI.corner(cap, "rSmall")
        local entry = { key = key, cap = cap, scale = UI.scaleOf(cap) }
        entry.stroke = UI.stroke(cap, "ink", "strokeA")
        entry.label = UI.text(cap, capLabel(key), "mono", "sub", { Name = "Label", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), TextSize = 11 })
        entry.what = UI.text(cap, "", "caption", "ink", { Name = "What", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -5), Size = UDim2.new(1, -6, 0, 11),
          AutomaticSize = Enum.AutomaticSize.None, TextSize = 9, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, Visible = false })
        Keys.caps[key] = entry
        paint(entry)
        UI.wire(cap, {
          hover = function(over)
            legend.Text = over and Keys.describe(key) or RESTING
            Theme.bind(legend, "TextColor3", over and (entry.clash and "warn" or "ink") or "sub")
            if not entry.held then Motion.to(entry.scale, "Scale", over and 1.05 or 1, "snappy") end
          end,
          click = function() UI.sfx("click", 0.6); Keys.menu(cap, key) end,
          alt = function() Keys.clear(key) end,
        })
      end
      x += item.width * (UNIT + GAP)
    end
  end
  -- a key pressed for real dips on the board: it is the quickest way to find out which one is which
  B.connect(UIS.InputBegan, function(input)
    local entry = Keys.caps[Config.keyName(input) or ""]
    if entry and entry.cap.Parent and Window.open and Window.current and Window.current.id == "keys" then
      entry.held = true
      Motion.to(entry.scale, "Scale", 0.9, "quick")
    end
  end, "keys.press")
  B.connect(UIS.InputEnded, function(input)
    local entry = Keys.caps[Config.keyName(input) or ""]
    if entry and entry.held then
      entry.held = false
      if entry.cap.Parent then Motion.to(entry.scale, "Scale", 1, "bouncy") end
    end
  end, "keys.release")
  Theme.changed:connect(function() if holder.Parent then Keys.repaint() end end)
end

-- ---------------------------------------------------------------- the list beside it
local function list(frame)
  local holder = UI.frame(frame, { Name = "Bound", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.list(holder, "y", 0)
  UI.pad(holder, 2, 0, 6, 0)
  function Keys.renderList()
    if not holder.Parent then return end
    for _, child in ipairs(holder:GetChildren()) do
      if child:IsA("Frame") or child:IsA("TextLabel") then child:Destroy() end
    end
    local binds = Keys.all()
    if #binds == 0 then
      local empty = UI.frame(holder, { Name = "Empty", Size = UDim2.new(1, 0, 0, 74) })
      UI.icon(empty, "keyboard", 20, "faint", { Position = UDim2.fromOffset(14, 14) })
      UI.text(empty, "Nothing is bound yet", "label", "ink", { Position = UDim2.fromOffset(44, 12) })
      UI.text(empty, "Click a key on the board, or right-click any switch in the hub and press the key you want for it.", "caption", "sub", { Position = UDim2.fromOffset(44, 32),
        Size = UDim2.new(1, -58, 0, 30), AutomaticSize = Enum.AutomaticSize.None, TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top, LineHeight = 1.15 })
      return
    end
    for index, bind in ipairs(binds) do
      local row = UI.frame(holder, { Name = "Bind_" .. bind.id, Size = UDim2.new(1, 0, 0, 40), LayoutOrder = index })
      if index > 1 then
        UI.frame(row, { Name = "Rule", Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
      end
      local chip = UI.frame(row, { Name = "Chip", Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), Size = UDim2.fromOffset(58, 24),
        Theme = { BackgroundColor3 = "accent" }, BackgroundTransparency = bind.on and 0 or 0.8 })
      UI.corner(chip, 7)
      UI.text(chip, Config.keyLabel(bind.key), "monoBold", bind.on and "accentInk" or "ink", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), TextSize = 11 })
      UI.text(row, bind.label, "label", "ink", { Name = "Feature", Position = UDim2.new(0, 84, 0.5, bind.page and -8 or 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13,
        Size = UDim2.new(1, -220, 0, 18), AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd })
      if bind.page then
        UI.text(row, bind.page, "caption", "faint", { Position = UDim2.new(0, 84, 0.5, 9), AnchorPoint = Vector2.new(0, 0.5), TextSize = 11 })
      end
      -- how the key works it: press to flip, hold to keep on, or simply run
      local mode = UI.pressable(row, { Name = "Mode", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -48, 0.5, 0), Size = UDim2.fromOffset(74, 24),
        Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
      UI.corner(mode, 7)
      UI.text(mode, bind.kind == "toggle" and (bind.mode == "hold" and "While held" or "Toggle") or "Runs it", "caption", bind.kind == "toggle" and "ink" or "faint",
        { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), TextSize = 11 })
      if bind.kind == "toggle" then
        UI.wire(mode, { click = function() UI.sfx("click", 0.5); Config.bind(bind.id, bind.key, bind.mode == "hold" and "toggle" or "hold") end })
      end
      local remove = UI.pressable(row, { Name = "Unbind", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(24, 24) })
      UI.corner(remove, 7)
      local cross = UI.icon(remove, "x", 14, "faint", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      UI.wire(remove, {
        hover = function(over) Theme.bind(cross, "ImageColor3", over and "bad" or "faint") end,
        click = function() UI.sfx("click", 0.5); Config.bind(bind.id, nil) end,
      })
    end
  end
  Keys.renderList()
end

-- ---------------------------------------------------------------- the list on screen
-- While the hub is hidden: each bound feature with its key, lit while it is on.
function Keys.hud()
  if Keys.panel or not Window.hud then return end
  local holder = UI.frame(Window.hud, { Name = "KeyList", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -16, 1, -16), Size = UDim2.fromOffset(0, 0),
    AutomaticSize = Enum.AutomaticSize.XY, Visible = false })
  local sizer = Instance.new("UIScale"); sizer.Scale = Window.scale or 1; sizer.Parent = holder
  local glass = UI.glass(holder, { level = "popover", radius = 14, shadow = 20, shadowY = 8, grain = false, props = { Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY } })
  local body = UI.frame(glass, { Name = "Body", Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY })
  UI.pad(body, 9, 12, 10, 12)
  UI.list(body, "y", 5)
  Keys.panel = holder
  local function shouldShow() return not Window.open and Config.get("app.keyHud") ~= false and next(Config.binds) ~= nil end
  function Keys.renderHud()
    if not holder.Parent then return end
    sizer.Scale = Window.scale or 1
    for _, child in ipairs(body:GetChildren()) do
      if child:IsA("Frame") or child:IsA("TextLabel") then child:Destroy() end
    end
    local binds = Keys.all()
    holder.Visible = shouldShow() and #binds > 0
    if not holder.Visible then return end
    UI.text(body, "KEYS", "eyebrow", "faint", { TextSize = 9, LayoutOrder = 0 })
    for index, bind in ipairs(binds) do
      if index > 9 then
        UI.text(body, "+" .. (#binds - 9) .. " more", "caption", "faint", { TextSize = 11, LayoutOrder = index })
        break
      end
      local row = UI.frame(body, { Name = "Bind_" .. bind.id, Size = UDim2.fromOffset(0, 20), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = index })
      UI.list(row, "x", 8, { v = "Center" })
      -- sized from its text: a chip that sizes itself left a single letter against its left edge
      local name = Config.keyLabel(bind.key)
      local chip = UI.frame(row, { Name = "Chip", Size = UDim2.fromOffset(math.max(28, #name * 7 + 14), 18), LayoutOrder = 1, Theme = { BackgroundColor3 = "accent" },
        BackgroundTransparency = bind.on and 0 or 0.8 })
      UI.corner(chip, 5)
      UI.text(chip, name, "monoBold", bind.on and "accentInk" or "ink", { TextSize = 10, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      UI.text(row, bind.label, "caption", bind.on and "ink" or "sub", { Name = "Feature", TextSize = 12, LayoutOrder = 2 })
    end
  end
  Window.onShow:connect(function() Keys.renderHud() end)
  Config.on("app.keyHud", function() Keys.renderHud() end)
  Keys.renderHud()
end

-- ---------------------------------------------------------------- the tab
function Keys.define()
  Config.define("app.keyHud", true)
end
B.pages[#B.pages + 1] = function()
  Keys.define()
  -- anything that changes what a key does, or whether a bound feature is on, redraws the board
  Config.bindsChanged:connect(function() Keys.repaint() end)
  Config.changed:connect(function(id)
    if Config.binds[id] or id == "app.key.menu" or id == "app.key.panic" or id == "fly.key.boost" or id == "fly.key.down" then Keys.repaint() end
  end)
  Config.loaded:connect(function() Keys.repaint() end)
  Window.page({ id = "keys", title = "Keys", icon = "keyboard", group = "Hub", order = 890, eyebrow = "What every key does", build = function(page)
    local map = page:section({ title = "Your keyboard", icon = "keyboard", full = true, desc = "Every key the hub listens to, and what it does." })
    map:custom({ height = Keys.height + 46, name = "Keyboard", build = board })

    local bound = page:section({ title = "Bound features", icon = "link", column = 1, weight = 6 })
    bound:custom({ name = "List", build = list })

    local own = page:section({ title = "The hub's own keys", icon = "command", column = 2, weight = 6 })
    own:keybind({ id = "app.key.menu", label = "Open / close the hub" })
    own:keybind({ id = "app.key.panic", label = "Panic", desc = "Unloads BASED instantly." })
    own:keybind({ id = "fly.key.boost", label = "Flight: boost", default = "LeftShift" })
    own:keybind({ id = "fly.key.down", label = "Flight: come down", default = "LeftControl" })
    own:toggle({ id = "app.keyHud", label = "Show my keys on screen", desc = "A small list in the corner while the hub is hidden, lit for whatever is on.", bindable = false })
    own:button({ label = "Clear every bound key", desc = "The hub's own keys are kept.", text = "Clear", style = "danger", bindable = false, run = function()
      local cleared = 0
      for id in pairs(table.clone(Config.binds)) do Config.bind(id, nil); cleared += 1 end
      Window.toast({ title = cleared == 0 and "Nothing was bound" or "Keys cleared", text = cleared > 0 and (cleared .. " features are off their keys.") or nil, icon = "keyboard" })
    end })
  end })
end
end
do -- 90_boot.lua
-- ============================================================================
--  90 boot     order of operations
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets
local UIS = S.UserInputService

local function boot()
  if not game:IsLoaded() then game.Loaded:Wait() end
  Config.init()
  Assets.init()
  if B.Prefs then B.Prefs.define() end
  if B.Prefs then B.Prefs.apply() end
  Window.build()
  for _, register in ipairs(B.pages or {}) do B.try("pages", register) end
  if B.Registry then B.try("registry", B.Registry.resolve) end
  Window.rebuildNav()
  Config.listen()

  -- the menu key, the palette, and the panic key
  B.connect(UIS.InputBegan, function(input)
    if Config.capturing then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    local name = input.KeyCode.Name
    if UIS:GetFocusedTextBox() then return end
    if name == Config.get("app.key.menu") then
      if B.Loader and B.Loader.active then return end
      Window.toggle()
    elseif name == Config.get("app.key.panic") then
      B.unload()
    elseif input.KeyCode == Enum.KeyCode.K and (UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)) and Window.open then
      Window.palette()
    end
  end, "boot.keys")

  local function reveal()
    Window.show(true)
    if B.Hud then B.try("hud", B.Hud.start) end
    if B.Keys then B.try("keys.hud", B.Keys.hud) end
    if B.Registry then B.try("registry.announce", B.Registry.announce) end
  end
  -- the other tabs are assembled a card per frame in the background: under the intro when there
  -- is one, so the hub is complete the moment it appears
  task.delay(0.7, function() if B.alive then Window.prebuild() end end)
  if B.Loader then B.Loader.run(reveal) else reveal() end
  B.bootMs = math.floor((os.clock() - B.bootClock) * 1000)
end

task.spawn(function()
  local ok, err = xpcall(boot, function(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end)
  if not ok then
    B.fault("boot", err)
    pcall(function()
      S.StarterGui:SetCore("SendNotification", { Title = "BASED Hub", Text = "Failed to start: " .. string.sub(tostring(err), 1, 120), Duration = 8 })
    end)
  end
end)
end
return B
